def upsert_entities(entities, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        # 26-char ULID (time + randomness), good enough for local datastore uniqueness
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(_CROCKFORD[ms & 31])
            ms //= 32
        chars = chars[::-1]
        for _ in range(16):
            chars.append(_CROCKFORD[random.getrandbits(5)])
        return "".join(chars)

    def _ensure_activity_log(event_type, status, request_obj, response_obj=None, error_message=None, entity_id=None, category=None, tags=None, context=None):
        logs = _load("activity_logs.json")
        ts = _now()
        row = {
            "id": _ulid(),
            "event_type": event_type,
            "status": status,
            "entity_id": entity_id,
            "category": category,
            "tags": tags,
            "context": context,
            "request": request_obj if isinstance(request_obj, dict) else {"value": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)
        return row

    t0 = time.time()
    # Validate inputs
    if not isinstance(entities, list):
        _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": None}, error_message="entities must be an array")
        return _err("VALIDATION_ERROR", "entities must be an array")

    for i, it in enumerate(entities):
        if not isinstance(it, dict):
            _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"entities[{i}] must be an object")
            return _err("VALIDATION_ERROR", f"entities[{i}] must be an object")
        allowed = {"name", "entityType", "observations", "context", "update"}
        unknown = set(it.keys()) - allowed
        if unknown:
            _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"Unknown fields in entities[{i}]: {sorted(list(unknown))}")
            return _err("VALIDATION_ERROR", f"Unknown fields in entities[{i}]", unknown_fields=sorted(list(unknown)))
        if "name" not in it or "entityType" not in it or "observations" not in it:
            _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"Missing required fields in entities[{i}]")
            return _err("VALIDATION_ERROR", f"Missing required fields in entities[{i}]")
        if not isinstance(it["name"], str) or len(it["name"].strip()) < 1:
            _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"entities[{i}].name must be a non-empty string")
            return _err("VALIDATION_ERROR", f"entities[{i}].name must be a non-empty string")
        if not isinstance(it["entityType"], str) or len(it["entityType"].strip()) < 1:
            _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"entities[{i}].entityType must be a non-empty string")
            return _err("VALIDATION_ERROR", f"entities[{i}].entityType must be a non-empty string")
        if not isinstance(it["observations"], list):
            _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"entities[{i}].observations must be an array of strings")
            return _err("VALIDATION_ERROR", f"entities[{i}].observations must be an array of strings")
        for j, ob in enumerate(it["observations"]):
            if not isinstance(ob, str) or len(ob.strip()) < 1:
                _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"entities[{i}].observations[{j}] must be a non-empty string")
                return _err("VALIDATION_ERROR", f"entities[{i}].observations[{j}] must be a non-empty string")
        if "context" in it and it["context"] is not None and not isinstance(it["context"], str):
            _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"entities[{i}].context must be a string")
            return _err("VALIDATION_ERROR", f"entities[{i}].context must be a string")
        if "update" in it and it["update"] is not None and not isinstance(it["update"], bool):
            _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"entities[{i}].update must be a boolean")
            return _err("VALIDATION_ERROR", f"entities[{i}].update must be a boolean")

    ents = _load("entities.json")
    obs = _load("observations.json")

    # Build indices
    by_name = {}
    for e in ents:
        if isinstance(e, dict) and "name" in e:
            by_name[e["name"]] = e

    now = _now()
    created = []
    updated = []
    unchanged = []
    results = []

    # Helper: get active observation content set for entity
    def _active_obs_for(entity_id):
        return [o for o in obs if o.get("entity_id") == entity_id and o.get("status") == "active"]

    def _normalize_contents(lst):
        # preserve duplicates? For "exactly provided observations" after replacement, we keep unique by content
        seen = set()
        out = []
        for s in lst:
            ss = s.strip()
            if ss not in seen:
                seen.add(ss)
                out.append(ss)
        return out

    # Process each entity item
    for it in entities:
        name = it["name"].strip()
        etype = it["entityType"].strip()
        context = it.get("context", None)
        update_flag = bool(it.get("update", False))
        provided_obs = _normalize_contents(it["observations"])

        existing = by_name.get(name)
        if existing is None:
            # Enforce unique(name): ok since absent
            eid = _ulid()
            e_row = {
                "id": eid,
                "name": name,
                "entity_type": etype,
                "context": context,
                "status": "active",
                "deleted_at": None,
                "created_at": now,
                "updated_at": now,
            }
            ents.append(e_row)
            by_name[name] = e_row

            # create obs
            for content in provided_obs:
                o_row = {
                    "id": _ulid(),
                    "entity_id": eid,
                    "content": content,
                    "context": context,
                    "tags": None,
                    "agent": None,
                    "source": "upsert_entities",
                    "source_ref_id": None,
                    "status": "active",
                    "deleted_at": None,
                    "created_at": now,
                    "updated_at": now,
                }
                obs.append(o_row)

            created.append(name)
            results.append(e_row)
        else:
            # If exists but deleted, treat as exists; update/create rules still apply based on update flag
            if not update_flag:
                unchanged.append(name)
                results.append(existing)
            else:
                # Update entity fields
                existing["entity_type"] = etype
                existing["context"] = context
                existing["updated_at"] = now
                # If previously deleted, lifecycle does not allow reactivation; keep deleted as-is
                # but tool says "fully replaced"; schema transitions disallow deleted->active
                if existing.get("status") == "deleted":
                    # Cannot update a deleted entity to active; still may update fields? To stay consistent, refuse.
                    _ensure_activity_log("system_config", "failed", {"endpoint": "upsert_entities", "entities": entities}, error_message=f"Cannot update deleted entity '{name}'")
                    return _err("INVALID_TRANSITION", f"Cannot update deleted entity '{name}'", name=name, from_status="deleted", to_status="active")

                # Replace observations: after call, active observations exactly equal provided_obs.
                active_obs = _active_obs_for(existing["id"])
                active_by_content = {}
                for o in active_obs:
                    active_by_content.setdefault(o.get("content"), []).append(o)

                provided_set = set(provided_obs)

                # Soft-delete prior active observations not present
                for o in active_obs:
                    if o.get("content") not in provided_set:
                        o["status"] = "deleted"
                        o["deleted_at"] = now
                        o["updated_at"] = now

                # Ensure each provided content has an active observation (create if none active)
                for content in provided_obs:
                    has_active = any((oo.get("status") == "active") for oo in active_by_content.get(content, []))
                    if not has_active:
                        o_row = {
                            "id": _ulid(),
                            "entity_id": existing["id"],
                            "content": content,
                            "context": context,
                            "tags": None,
                            "agent": None,
                            "source": "upsert_entities",
                            "source_ref_id": None,
                            "status": "active",
                            "deleted_at": None,
                            "created_at": now,
                            "updated_at": now,
                        }
                        obs.append(o_row)

                updated.append(name)
                results.append(existing)

    _save("entities.json", ents)
    _save("observations.json", obs)

    latency_ms = int((time.time() - t0) * 1000)
    _ensure_activity_log(
        "system_config",
        "succeeded",
        {"endpoint": "upsert_entities", "entities_count": len(entities)},
        response_obj={"created": created, "updated": updated, "unchanged": unchanged, "latency_ms": latency_ms},
    )

    return {
        "entities": results,
        "summary": {"created": created, "updated": updated, "unchanged": unchanged},
    }

def create_relations(relations, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32])
            v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, request_obj, response_obj=None, error_message=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status,
            "entity_id": None,
            "category": "create_relations",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    t0 = time.time()
    if _extra:
        _log("failed", {"relations": relations, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(relations, list):
        _log("failed", {"relations": relations}, error_message="relations must be an array")
        return _err("VALIDATION_ERROR", "relations must be an array")

    allowed_keys = {"from", "to", "relationType"}
    for i, it in enumerate(relations):
        if not isinstance(it, dict):
            _log("failed", {"relations": relations}, error_message=f"relations[{i}] must be an object")
            return _err("VALIDATION_ERROR", f"relations[{i}] must be an object")
        extra_keys = set(it.keys()) - allowed_keys
        if extra_keys:
            _log("failed", {"relations": relations}, error_message=f"Unknown fields in relations[{i}]")
            return _err("VALIDATION_ERROR", f"Unknown fields in relations[{i}].", unknown_fields=sorted(list(extra_keys)))
        for k in ("from", "to", "relationType"):
            v = it.get(k)
            if not isinstance(v, str) or len(v.strip()) < 1:
                _log("failed", {"relations": relations}, error_message=f"relations[{i}].{k} must be a non-empty string")
                return _err("VALIDATION_ERROR", f"relations[{i}].{k} must be a non-empty string")
        # Important: tool schema does NOT forbid from==to; business rules forbid it, but audit showed callers pass ids.
        # We accept by treating values as "entity lookup keys" that may be either name or id, and only forbid true self-edge by entity_id.

    entities = _load("entities.json")
    rels = _load("relations.json")

    ent_by_name = {}
    ent_by_id = {}
    for e in entities:
        if isinstance(e, dict):
            if e.get("name"):
                ent_by_name[e.get("name")] = e
            if e.get("id"):
                ent_by_id[e.get("id")] = e

    def _resolve_entity(ref):
        # ref can be entity name (tool intended) OR an entity id (seen in audit args)
        e = ent_by_name.get(ref) or ent_by_id.get(ref)
        if not e:
            return None
        if e.get("status") != "active":
            return None
        return e

    created = []
    conflicts = []
    not_founds = []
    validation = []

    now = _now_z()

    # Precompute active unique triples
    active_triples = set()
    for rr in rels:
        if isinstance(rr, dict) and rr.get("status") == "active":
            active_triples.add((rr.get("from_entity_id"), rr.get("to_entity_id"), rr.get("relation_type")))

    for i, r in enumerate(relations):
        f_ref = r.get("from")
        t_ref = r.get("to")
        rtype = r.get("relationType").strip()

        f_ent = _resolve_entity(f_ref)
        t_ent = _resolve_entity(t_ref)

        if f_ent is None:
            not_founds.append({"index": i, "from": f_ref, "field": "from"})
            continue
        if t_ent is None:
            not_founds.append({"index": i, "to": t_ref, "field": "to"})
            continue

        f_id = f_ent.get("id")
        t_id = t_ent.get("id")

        if f_id == t_id:
            # Business rule: from_entity_id <> to_entity_id
            validation.append({"index": i, "message": "from and to must be different entities", "from": f_ref, "to": t_ref})
            continue

        key = (f_id, t_id, rtype)
        if key in active_triples:
            conflicts.append({"index": i, "message": "Relation already exists", "from": f_ref, "to": t_ref, "relationType": rtype})
            continue

        # Create
        new_row = {
            "id": _ulid("tt_rel_"),
            "from_entity_id": f_id,
            "to_entity_id": t_id,
            "relation_type": rtype,
            "status": "active",
            "deleted_at": None,
            "created_at": now,
            "updated_at": now,
        }
        rels.append(new_row)
        active_triples.add(key)
        created.append(new_row)

    # If any NOT_FOUND or VALIDATION errors occurred, behave like real API would: do not partially succeed unless vendor says.
    # Description says: Raises NOT_FOUND when either endpoint entity name does not exist, and CONFLICT when identical exists.
    # We'll prioritize VALIDATION > NOT_FOUND > CONFLICT, and avoid partial mutation if any error occurred.
    if validation or not_founds or conflicts:
        # rollback by reloading original and only saving if no error
        # We already appended; so undo by reloading from disk (original) and not saving.
        code = "VALIDATION_ERROR" if validation else ("NOT_FOUND" if not_founds else "CONFLICT")
        msg = (
            validation[0]["message"] if validation else
            ("Entity not found." if not_founds else "Identical relation already exists.")
        )
        detail = {"validation": validation, "not_found": not_founds, "conflicts": conflicts}
        _log("failed", {"relations": relations}, error_message=msg, response_obj=detail)
        return _err(code, msg, **detail)

    _save("relations.json", rels)
    latency_ms = int((time.time() - t0) * 1000)
    _log("succeeded", {"relations": relations, "latency_ms": latency_ms}, response_obj={"relations": created})

    return {"relations": created}

def add_observations(observations, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(_CROCKFORD[ms & 31])
            ms //= 32
        chars = chars[::-1]
        for _ in range(16):
            chars.append(_CROCKFORD[random.getrandbits(5)])
        return "".join(chars)

    def _ensure_activity_log(event_type, status, request_obj, response_obj=None, error_message=None, entity_id=None, category=None, tags=None, context=None):
        logs = _load("activity_logs.json")
        ts = _now()
        row = {
            "id": _ulid(),
            "event_type": event_type,
            "status": status,
            "entity_id": entity_id,
            "category": category,
            "tags": tags,
            "context": context,
            "request": request_obj if isinstance(request_obj, dict) else {"value": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)
        return row

    t0 = time.time()

    if not isinstance(observations, list):
        _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations": None}, error_message="observations must be an array")
        return _err("VALIDATION_ERROR", "observations must be an array")

    for i, it in enumerate(observations):
        if not isinstance(it, dict):
            _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations": observations}, error_message=f"observations[{i}] must be an object")
            return _err("VALIDATION_ERROR", f"observations[{i}] must be an object")
        allowed = {"entityName", "contents"}
        unknown = set(it.keys()) - allowed
        if unknown:
            _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations": observations}, error_message=f"Unknown fields in observations[{i}]")
            return _err("VALIDATION_ERROR", f"Unknown fields in observations[{i}]", unknown_fields=sorted(list(unknown)))
        if "entityName" not in it or "contents" not in it:
            _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations": observations}, error_message=f"Missing required fields in observations[{i}]")
            return _err("VALIDATION_ERROR", f"Missing required fields in observations[{i}]")
        if not isinstance(it["entityName"], str) or len(it["entityName"].strip()) < 1:
            _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations": observations}, error_message=f"observations[{i}].entityName must be a non-empty string")
            return _err("VALIDATION_ERROR", f"observations[{i}].entityName must be a non-empty string")
        if not isinstance(it["contents"], list):
            _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations": observations}, error_message=f"observations[{i}].contents must be an array of strings")
            return _err("VALIDATION_ERROR", f"observations[{i}].contents must be an array of strings")
        for j, c in enumerate(it["contents"]):
            if not isinstance(c, str):
                _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations": observations}, error_message=f"observations[{i}].contents[{j}] must be a string")
                return _err("VALIDATION_ERROR", f"observations[{i}].contents[{j}] must be a string")
            if len(c.strip()) < 1:
                _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations": observations}, error_message=f"observations[{i}].contents[{j}] must be a non-empty string")
                return _err("VALIDATION_ERROR", f"observations[{i}].contents[{j}] must be a non-empty string")

    ents = _load("entities.json")
    obs = _load("observations.json")

    ent_by_name = {}
    for e in ents:
        if isinstance(e, dict) and isinstance(e.get("name"), str):
            ent_by_name[e["name"]] = e

    # Existence check
    missing = []
    deleted = []
    for it in observations:
        nm = it["entityName"].strip()
        e = ent_by_name.get(nm)
        if e is None:
            missing.append(nm)
        elif e.get("status") != "active":
            deleted.append(nm)
    if missing:
        _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations_count": len(observations)}, error_message="Entity not found")
        return _err("NOT_FOUND", "Entity not found", missing=missing)
    if deleted:
        _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations_count": len(observations)}, error_message="Entity is deleted")
        return _err("NOT_FOUND", "Entity is deleted", deleted=deleted)

    now = _now()
    added = []
    per_entity = {}

    # Optional dedup: only if identical content already active for same entity AND agent within short window.
    # This tool surface has no agent param, so treat agent as None, and window as 60 seconds.
    window_seconds = 60

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            # accepts "...Z"
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    for it in observations:
        nm = it["entityName"].strip()
        e = ent_by_name[nm]
        eid = e["id"]
        contents = [c.strip() for c in it["contents"]]
        for content in contents:
            # dedup check
            dup = False
            for o in obs:
                if o.get("entity_id") != eid:
                    continue
                if o.get("status") != "active":
                    continue
                if o.get("content") != content:
                    continue
                if o.get("agent") is not None:
                    continue
                ts = _parse_ts(o.get("created_at"))
                if ts is None:
                    continue
                if abs((_parse_ts(now) - ts).total_seconds()) <= window_seconds:
                    dup = True
                    break
            if dup:
                continue
            o_row = {
                "id": _ulid(),
                "entity_id": eid,
                "content": content,
                "context": None,
                "tags": None,
                "agent": None,
                "source": "add_observations",
                "source_ref_id": None,
                "status": "active",
                "deleted_at": None,
                "created_at": now,
                "updated_at": now,
            }
            obs.append(o_row)
            added.append(o_row)
            per_entity.setdefault(nm, []).append(o_row)

        # touch entity updated_at
        e["updated_at"] = now

    if not added:
        # No success without effect: if everything deduped, treat as conflict-ish? Spec doesn't define.
        _ensure_activity_log("system_config", "failed", {"endpoint": "add_observations", "observations_count": len(observations)}, error_message="No observations added")
        return _err("CONFLICT", "No observations added (all duplicates within dedup window)")

    _save("observations.json", obs)
    _save("entities.json", ents)

    latency_ms = int((time.time() - t0) * 1000)
    _ensure_activity_log(
