def delete_entities(entityNames, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(_CROCKFORD[ms & 31])
            ms //= 32
        chars = chars[::-1]
        for _ in range(16):
            chars.append(_CROCKFORD[random.getrandbits(5)])
        return "".join(chars)

    def _ensure_activity_log(event_type, status, request_obj, response_obj=None, error_message=None, entity_id=None, category=None, tags=None, context=None):
        logs = _load("activity_logs.json")
        ts = _now()
        row = {
            "id": _ulid(),
            "event_type": event_type,
            "status": status,
            "entity_id": entity_id,
            "category": category,
            "tags": tags,
            "context": context,
            "request": request_obj if isinstance(request_obj, dict) else {"value": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)
        return row

    t0 = time.time()

    if not isinstance(entityNames, list):
        _ensure_activity_log("system_config", "failed", {"endpoint": "delete_entities", "entityNames": None}, error_message="entityNames must be an array")
        return _err("VALIDATION_ERROR", "entityNames must be an array")

    names = []
    for i, nm in enumerate(entityNames):
        if not isinstance(nm, str) or len(nm.strip()) < 1:
            _ensure_activity_log("system_config", "failed", {"endpoint": "delete_entities", "entityNames": entityNames}, error_message=f"entityNames[{i}] must be a non-empty string")
            return _err("VALIDATION_ERROR", f"entityNames[{i}] must be a non-empty string")
        names.append(nm.strip())

    ents = _load("entities.json")
    obs = _load("observations.json")
    rels = _load("relations.json")

    ent_by_name = {}
    for e in ents:
        if isinstance(e, dict) and isinstance(e.get("name"), str):
            ent_by_name[e["name"]] = e

    missing = [nm for nm in names if nm not in ent_by_name]
    if missing:
        _ensure_activity_log("system_config", "failed", {"endpoint": "delete_entities", "entityNames": names}, error_message="Entity not found")
        return _err("NOT_FOUND", "Entity not found", missing=missing)

    now = _now()
    deleted_entities = []
    already_deleted = []
    deleted_observations = 0
    deleted_relations = 0

    target_ids = set()

    # Soft-delete entities
    for nm in names:
        e = ent_by_name[nm]
        if e.get("status") == "deleted":
            already_deleted.append(nm)
            target_ids.add(e.get("id"))
            continue
        e["status"] = "deleted"
        e["deleted_at"] = now
        e["updated_at"] = now
        deleted_entities.append(nm)
        target_ids.add(e.get("id"))

    # Cascade soft-delete active relations where either endpoint matches
    for r in rels:
        if r.get("status") != "active":
            continue
        if r.get("from_entity_id") in target_ids or r.get("to_entity_id") in target_ids:
            r["status"] = "deleted"
            r["deleted_at"] = now
            r["updated_at"] = now
            deleted_relations += 1

    # Soft-delete observations for those entities
    for o in obs:
        if o.get("status") != "active":
            continue
        if o.get("entity_id") in target_ids:
            o["status"] = "deleted"
            o["deleted_at"] = now
            o["updated_at"] = now
            deleted_observations += 1

    if not deleted_entities and deleted_relations == 0 and deleted_observations == 0:
        # No success without effect: if all requested were already deleted and no active children, return NOT_FOUND-ish?
        _ensure_activity_log("system_config", "failed", {"endpoint": "delete_entities", "entityNames": names}, error_message="Nothing to delete")
        return _err("NOT_FOUND", "Nothing to delete (entities already deleted)", already_deleted=already_deleted)

    _save("entities.json", ents)
    _save("relations.json", rels)
    _save("observations.json", obs)

    latency_ms = int((time.time() - t0) * 1000)
    _ensure_activity_log(
        "system_config",
        "succeeded",
        {"endpoint": "delete_entities", "entityNames": names},
        response_obj={
            "deleted_entities": deleted_entities,
            "already_deleted": already_deleted,
            "deleted_relations": deleted_relations,
            "deleted_observations": deleted_observations,
            "latency_ms": latency_ms,
        },
    )

    return {
        "summary": {
            "deleted_entities": deleted_entities,
            "already_deleted": already_deleted,
            "deleted_relations": deleted_relations,
            "deleted_observations": deleted_observations,
        }
    }

def delete_observations(deletions, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32]); v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, request_obj, response_obj=None, error_message=None, entity_id=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status,
            "entity_id": entity_id,
            "category": "delete_observations",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    if _extra:
        _append_log("failed", {"deletions": deletions, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(deletions, list):
        _append_log("failed", {"deletions": deletions}, error_message="deletions must be an array.")
        return _err("VALIDATION_ERROR", "deletions must be an array.", field="deletions")

    allowed_keys = {"entityName", "observations"}
    for i, d in enumerate(deletions):
        if not isinstance(d, dict):
            _append_log("failed", {"deletions": deletions}, error_message="Each deletions item must be an object.")
            return _err("VALIDATION_ERROR", "Each deletions item must be an object.", index=i)
        extra_keys = set(d.keys()) - allowed_keys
        if extra_keys:
            _append_log("failed", {"deletions": deletions}, error_message="Unknown fields in deletions item.")
            return _err("VALIDATION_ERROR", "Unknown fields provided in deletions item.", index=i, unknown_fields=sorted(list(extra_keys)))
        if "entityName" not in d or "observations" not in d:
            _append_log("failed", {"deletions": deletions}, error_message="Missing required fields in deletions item.")
            return _err("VALIDATION_ERROR", "Missing required fields in deletions item.", index=i, required=["entityName", "observations"])
        if not isinstance(d["entityName"], str) or not d["entityName"].strip():
            _append_log("failed", {"deletions": deletions}, error_message="entityName must be a non-empty string.")
            return _err("VALIDATION_ERROR", "entityName must be a non-empty string.", index=i, field="entityName")
        if not isinstance(d["observations"], list):
            _append_log("failed", {"deletions": deletions}, error_message="observations must be an array of strings.")
            return _err("VALIDATION_ERROR", "observations must be an array of strings.", index=i, field="observations")
        for j, obs in enumerate(d["observations"]):
            if not isinstance(obs, str):
                _append_log("failed", {"deletions": deletions}, error_message="observations entries must be strings.")
                return _err("VALIDATION_ERROR", "observations entries must be strings.", index=i, obs_index=j, field="observations")

    entities = _load("entities.json")
    observations = _load("observations.json")

    # resolve entities first; fail NOT_FOUND if any entity missing or deleted
    name_to_entity = {}
    missing_entities = []
    for i, d in enumerate(deletions):
        nm = d["entityName"].strip()
        ent = next((e for e in entities if isinstance(e, dict) and e.get("name") == nm and e.get("status") == "active"), None)
        if not ent:
            missing_entities.append({"index": i, "entityName": nm})
        else:
            name_to_entity[nm] = ent
    if missing_entities:
        _append_log("failed", {"deletions": deletions}, error_message="Entity not found.")
        return _err("NOT_FOUND", "Entity not found.", missing=missing_entities)

    # Determine matches; support legacy clients that pass observation ids in place of content:
    # match by (entity_id AND (content==value OR id==value)) among active observations.
    missing_obs = []
    to_delete_ids = []
    for i, d in enumerate(deletions):
        nm = d["entityName"].strip()
        ent = name_to_entity[nm]
        ent_id = ent.get("id")
        for obs_val in d["observations"]:
            candidates = [
                o for o in observations
                if isinstance(o, dict)
                and o.get("entity_id") == ent_id
                and o.get("status") == "active"
                and (o.get("content") == obs_val or o.get("id") == obs_val)
            ]
            if not candidates:
                missing_obs.append({"index": i, "entityName": nm, "observation": obs_val})
            else:
                # delete all matching candidates (content duplicates are allowed)
                for o in candidates:
                    to_delete_ids.append(o.get("id"))
    if missing_obs:
        _append_log("failed", {"deletions": deletions}, error_message="Observation not found on entity.")
        return _err("NOT_FOUND", "Observation not found on entity.", missing=missing_obs)

    now = _now_z()
    deleted_count = 0
    deleted_ids_set = set(to_delete_ids)
    for o in observations:
        if isinstance(o, dict) and o.get("id") in deleted_ids_set and o.get("status") == "active":
            o["status"] = "deleted"
            o["deleted_at"] = now
            o["updated_at"] = now
            deleted_count += 1

    if deleted_count <= 0:
        _append_log("failed", {"deletions": deletions}, error_message="No matching active observations to delete.")
        return _err("NOT_FOUND", "No matching active observations to delete.")

    _save("observations.json", observations)

    # return updated entity records (active only) with remaining active observations
    updated_entities = []
    for nm, ent in name_to_entity.items():
        ent_id = ent.get("id")
        ent_obs = [
            o for o in observations
            if isinstance(o, dict) and o.get("entity_id") == ent_id and o.get("status") == "active"
        ]
        updated_entities.append({
            "id": ent.get("id"),
            "name": ent.get("name"),
            "entityType": ent.get("entity_type"),
            "context": ent.get("context"),
            "status": ent.get("status"),
            "observations": [o.get("content") for o in sorted(ent_obs, key=lambda x: (x.get("created_at") or "", x.get("id") or ""))],
            "updatedAt": ent.get("updated_at"),
        })

    resp = {
        "deletedCount": deleted_count,
        "entities": updated_entities,
    }
    _append_log("succeeded", {"deletions": deletions}, response_obj=resp)
    return resp

def delete_relations(relations, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32])
            v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, request_obj, response_obj=None, error_message=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status,
            "entity_id": None,
            "category": "delete_relations",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    t0 = time.time()
    if _extra:
        _log("failed", {"relations": relations, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(relations, list):
        _log("failed", {"relations": relations}, error_message="relations must be an array.")
        return _err("VALIDATION_ERROR", "relations must be an array.")

    allowed_keys = {"from", "to", "relationType"}
    for i, r in enumerate(relations):
        if not isinstance(r, dict):
            _log("failed", {"relations": relations}, error_message=f"relations[{i}] must be an object.")
            return _err("VALIDATION_ERROR", f"relations[{i}] must be an object.")
        extra_keys = set(r.keys()) - allowed_keys
        if extra_keys:
            _log("failed", {"relations": relations}, error_message=f"Unknown fields in relations[{i}].")
            return _err("VALIDATION_ERROR", f"Unknown fields in relations[{i}].", unknown_fields=sorted(list(extra_keys)))
        for k in ("from", "to", "relationType"):
            v = r.get(k)
            if not isinstance(v, str) or len(v.strip()) < 1:
                _log("failed", {"relations": relations}, error_message=f"relations[{i}].{k} must be a non-empty string.")
                return _err("VALIDATION_ERROR", f"relations[{i}].{k} must be a non-empty string.")

    entities = _load("entities.json")
    rel_rows = _load("relations.json")

    ent_by_name = {e.get("name"): e for e in entities if isinstance(e, dict) and e.get("name")}
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and e.get("id")}

    def _resolve_entity(ref):
        e = ent_by_name.get(ref) or ent_by_id.get(ref)
        if not e:
            return None
        # Deleting relations for deleted entities: tool description says NOT_FOUND when from/to don't correspond;
        # treat deleted entities as not found to avoid surfacing deleted content.
        if e.get("status") != "active":
            return None
        return e

    # Precheck: require relation exists (active or deleted) and endpoints exist
    missing = []
    now = _now_z()

    def _find_relation(f_id, t_id, rtype):
        for rr in rel_rows:
            if isinstance(rr, dict) and rr.get("from_entity_id") == f_id and rr.get("to_entity_id") == t_id and rr.get("relation_type") == rtype:
                return rr
        return None

    for i, r in enumerate(relations):
        f = _resolve_entity(r["from"])
        t = _resolve_entity(r["to"])
        if f is None or t is None:
            missing.append({"index": i, "message": "from/to entity not found", "from": r["from"], "to": r["to"], "relationType": r["relationType"]})
            continue
        rr = _find_relation(f["id"], t["id"], r["relationType"].strip())
        if rr is None:
            missing.append({"index": i, "message": "relation not found", "from": r["from"], "to": r["to"], "relationType": r["relationType"]})

    if missing:
        msg = "Relation not found."
        _log("failed", {"relations": relations}, error_message=msg, response_obj={"not_found": missing})
        return _err("NOT_FOUND", msg, not_found=missing)

    # Apply delete (idempotent at row-level, but endpoint is NOT_FOUND if nonexistent; we prechecked)
    deleted = 0
    results = []
    for r in relations:
        f = _resolve_entity(r["from"])
        t = _resolve_entity(r["to"])
        rtype = r["relationType"].strip()
        rr = _find_relation(f["id"], t["id"], rtype)
        if rr.get("status") != "deleted":
            rr["status"] = "deleted"
            rr["deleted_at"] = now
            rr["updated_at"] = now
            deleted += 1
        results.append({"from": r["from"], "to": r["to"], "relationType": rtype, "status": rr.get("status"), "id": rr.get("id")})

    if deleted == 0:
        # All were already deleted; still an effect? No. But since they exist and request is valid,
        # real systems may treat as idempotent success. Tool description doesn't specify. We'll return succeeded with unchanged.
        pass

    _save("relations.json", rel_rows)
    latency_ms = int((time.time() - t0) * 1000)
    _log("succeeded", {"relations": relations, "latency_ms": latency_ms}, response_obj={"deleted": deleted, "results": results})
    return {"deleted": deleted, "results": results}

def read_graph(dummy=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("activity_logs.json")

    def _new_ulid():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

        def enc(v, n):
            out = ""
            for _ in range(n):
                out = alphabet[v % 32] + out
                v //= 32
            return out

        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        return enc(ms, 10) + enc(r, 16)

    def _log(status, request, response=None, error_message=None):
        now = _now()
        row = {
            "id": _new_ulid(),
            "event_type": "think",
            "status": status,
            "entity_id": None,
            "category": None,
            "tags": None,
            "context": None,
            "request": request,
            "response": response,
            "memory_path": None,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    # Validation: no unexpected parameters (additionalProperties=false). dummy is allowed.
    if _extra:
        _log("failed", {"tool": "read_graph", "dummy": dummy, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    entities = _load("entities.json")
    observations = _load("observations.json")
    relations = _load("relations.json")

    active_entities = [e for e in entities if isinstance(e, dict) and e.get("status") == "active"]
    active_entity_ids = set([e.get("id") for e in active_entities if e.get("id")])

    active_observations = [
        o for o in observations
        if isinstance(o, dict) and o.get("status") == "active" and o.get("entity_id") in active_entity_ids
    ]

    active_relations = [
        r for r in relations
        if isinstance(r, dict)
        and r.get("status") == "active"
        and r.get("from_entity_id") in active_entity_ids
        and r.get("to_entity_id") in active_entity_ids
    ]

    # Assemble graph
    obs_by_entity = {}
    for o in active_observations:
        obs_by_entity.setdefault(o.get("entity_id"), []).append(o)

    entities_out = []
    for e in sorted(active_entities, key=lambda x: (str(x.get("name") or "").lower(), x.get("id") or "")):
        ent_obs = obs_by_entity.get(e.get("id"), [])
        entities_out.append(
            {
                "id": e.get("id"),
                "name": e.get("name"),
                "entityType": e.get("entity_type"),
                "context": e.get("context"),
                "created_at": e.get("created_at"),
                "updated_at": e.get("updated_at"),
                "observations": [
                    {
                        "id": o.get("id"),
                        "content": o.get("content"),
                        "context": o.get("context"),
                        "tags": o.get("tags"),
                        "agent": o.get("agent"),
                        "source": o.get("source"),
                        "source_ref_id": o.get("source_ref_id"),
                        "created_at": o.get("created_at"),
                        "updated_at": o.get("updated_at"),
                    }
                    for o in sorted(ent_obs, key=lambda x: (x.get("created_at") or "", x.get("id") or ""))
                ],
            }
        )

    # Resolve relation endpoints to names for client convenience
    id_to_name = {e.get("id"): e.get("name") for e in active_entities if e.get("id")}
    relations_out = []
    for r in sorted(active_relations, key=lambda x: (x.get("from_entity_id") or "", x.get("to_entity_id") or "", x.get("relation_type") or "")):
        relations_out.append(
            {
                "id": r.get("id"),
                "from": id_to_name.get(r.get("from_entity_id")),
                "to": id_to_name.get(r.get("to_entity_id")),
                "relationType": r.get("relation_type"),
                "created_at": r.get("created_at"),
                "updated_at": r.get("updated_at"),
            }
        )

    resp = {
        "entities": entities_out,
        "relations": relations_out,
        "counts": {
            "entities": len(entities_out),
            "observations": len(active_observations),
            "relations": len(relations_out),
        },
    }
    _log("succeeded", {"tool": "read_graph", "dummy": dummy}, response=resp)
    return resp

def search_nodes(query, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32])
            v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_activity(call_status, request_obj, response_obj=None, error_message=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": call_status,
            "entity_id": None,
            "category": "search_nodes",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)
        return row

    if _extra:
        _append_activity("failed", {"query": query, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(query, str) or not query.strip():
        _append_activity("failed", {"query": query}, error_message="query must be a non-empty string")
        return _err("VALIDATION_ERROR", "query must be a non-empty string.", field="query")

    q = query.strip().lower()
    entities = _load("entities.json")

    matches = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("status") != "active":
            continue
        name = e.get("name") or ""
        etype = e.get("entity_type") or ""
        if not isinstance(name, str):
            name = ""
        if not isinstance(etype, str):
            etype = ""
        hay = (name + " " + etype).lower()
        if q in hay:
            matches.append(e)

    # deterministic order: name asc, then created_at asc
    def _k(e):
        nm = e.get("name") or ""
        ca = e.get("created_at") or ""
        return (str(nm).lower(), str(ca))
    matches.sort(key=_k)

    resp = {"query": query, "nodes": matches, "count": len(matches)}
    _append_activity("succeeded", {"query": query}, response_obj={"count": len(matches)})
    return resp

def open_nodes(names, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_nonempty_str(x):
        return isinstance(x, str) and len(x) >= 1

    def _gen_ulid():
        # Not a real ULID, but stable "looks like" unique id and sortable-ish.
        t = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{t:012x}{rnd:020x}"

    t0 = time.time()
    status = "failed"
    err = None

    # Validate
    if names is None:
        err = _err("VALIDATION_ERROR", "Missing required field: names")
    elif not isinstance(names, list):
        err = _err("VALIDATION_ERROR", "Field 'names' must be an array of strings")
    else:
        for i, n in enumerate(names):
            if not _is_nonempty_str(n):
                err = _err("VALIDATION_ERROR", f"names[{i}] must be a non-empty string")
                break

    # Load data
    entities = _load("entities.json")
    observations = _load("observations.json")
    relations = _load("relations.json")
    activity_logs = _load("activity_logs.json")

    # Execute
    result = None
    if err is None:
        name_set = set(names)
        ent_by_name = {e.get("name"): e for e in entities if isinstance(e, dict)}
        active_entities = {}
        not_found = []
        for nm in names:
            e = ent_by_name.get(nm)
            if not e or e.get("status") != "active":
                not_found.append(nm)
            else:
                active_entities[nm] = e

        if not_found:
            err = _err("NOT_FOUND", "One or more requested entities do not exist", not_found=not_found)
        else:
            # Build node records: entity + its active observations + relations touching it (active)
            ent_ids = {e["id"] for e in active_entities.values() if isinstance(e.get("id"), str)}
            obs_by_entity = {}
            for o in observations:
                if not isinstance(o, dict):
                    continue
                if o.get("status") != "active":
                    continue
                eid = o.get("entity_id")
                if eid in ent_ids:
                    obs_by_entity.setdefault(eid, []).append(o)

            rels_for = {}
            for r in relations:
                if not isinstance(r, dict):
                    continue
                if r.get("status") != "active":
                    continue
                fe = r.get("from_entity_id")
                te = r.get("to_entity_id")
                if fe in ent_ids or te in ent_ids:
                    rels_for.setdefault(fe, [])
                    rels_for.setdefault(te, [])
                    if fe in ent_ids:
                        rels_for[fe].append(r)
                    if te in ent_ids and te != fe:
                        rels_for[te].append(r)

            nodes = []
            # Return as single set; preserve input order
            for nm in names:
                e = active_entities[nm]
                eid = e["id"]
                nodes.append({
                    "entity": e,
                    "observations": sorted(obs_by_entity.get(eid, []), key=lambda x: x.get("created_at") or ""),
                    "relations": sorted(rels_for.get(eid, []), key=lambda x: x.get("created_at") or "")
                })

            result = {"nodes": nodes}

    # Log call (observable dynamics)
    try:
        log_row = {
            "id": _gen_ulid(),
            "event_type": "system_config",
            "status": "failed" if err else "succeeded",
            "entity_id": None,
            "category": "open_nodes",
            "tags": None,
            "context": None,
            "request": {"names": names},
            "response": None if err else {"count": len(result.get("nodes", []))},
            "memory_path": os.path.abspath(_DB),
            "error_message": None if not err else err["error"]["message"],
            "created_at": _now(),
            "updated_at": _now()
        }
        activity_logs.append(log_row)
        _save("activity_logs.json", activity_logs)
    except Exception:
        # Must not raise; return original outcome
        pass

    if err:
        return err
    return {"nodes": result["nodes"]}

def update_relations(relations, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32])
            v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, request_obj, response_obj=None, error_message=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status,
            "entity_id": None,
            "category": "update_relations",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    t0 = time.time()
    if _extra:
        _log("failed", {"relations": relations, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if relations is None or not isinstance(relations, list):
        _log("failed", {"relations": relations}, error_message="relations must be an array")
        return _err("VALIDATION_ERROR", "relations must be an array")

    allowed_keys = {"from", "to", "relationType"}
    for i, r in enumerate(relations):
        if not isinstance(r, dict):
            _log("failed", {"relations": relations}, error_message=f"relations[{i}] must be an object")
            return _err("VALIDATION_ERROR", f"relations[{i}] must be an object")
        extra_keys = set(r.keys()) - allowed_keys
        if extra_keys:
            _log("failed", {"relations": relations}, error_message=f"Unknown fields in relations[{i}].")
            return _err("VALIDATION_ERROR", f"Unknown fields in relations[{i}].", unknown_fields=sorted(list(extra_keys)))
        for k in ("from", "to", "relationType"):
            v = r.get(k)
            if not isinstance(v, str) or len(v.strip()) < 1:
                _log("failed", {"relations": relations}, error_message=f"relations[{i}].{k} must be a non-empty string")
                return _err("VALIDATION_ERROR", f"relations[{i}].{k} must be a non-empty string")

    entities = _load("entities.json")
    rel_rows = _load("relations.json")

    ent_by_name = {e.get("name"): e for e in entities if isinstance(e, dict) and e.get("name")}
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and e.get("id")}

    def _resolve_entity(ref):
        e = ent_by_name.get(ref) or ent_by_id.get(ref)
        if not e:
            return None
        if e.get("status") != "active":
            return None
        return e

    def _find_relation(f_id, t_id, rtype):
        for rr in rel_rows:
            if isinstance(rr, dict) and rr.get("from_entity_id") == f_id and rr.get("to_entity_id") == t_id and rr.get("relation_type") == rtype:
                return rr
        return None

    # Must already exist; if deleted, reactivate. If not exist => NOT_FOUND.
    not_found = []
    now = _now_z()
    updated = []

    for i, r in enumerate(relations):
        f = _resolve_entity(r["from"])
        t = _resolve_entity(r["to"])
        if f is None or t is None:
            not_found.append({"index": i, "message": "from/to entity not found", "from": r["from"], "to": r["to"], "relationType": r["relationType"]})
            continue
        rtype = r["relationType"].strip()
        rr = _find_relation(f["id"], t["id"], rtype)
        if rr is None:
            not_found.append({"index": i, "message": "relation not found", "from": r["from"], "to": r["to"], "relationType": rtype})
            continue

    if not_found:
        msg = "Relation not found."
        _log("failed", {"relations": relations}, error_message=msg, response_obj={"not_found": not_found})
        return _err("NOT_FOUND", msg, not_found=not_found)

    # Apply (reactivate if deleted)
    changed = 0
    for r in relations:
        f = _resolve_entity(r["from"])
        t = _resolve_entity(r["to"])
        rtype = r["relationType"].strip()
        rr = _find_relation(f["id"], t["id"], rtype)
        if rr.get("status") == "deleted":
            rr["status"] = "active"
            rr["deleted_at"] = None
            rr["updated_at"] = now
            changed += 1
        else:
            # no-op update; still return record
            rr["updated_at"] = rr.get("updated_at") or now
        updated.append(rr)

    if changed == 0:
        # No status change occurred; still an "update" call, but it had no effect. Real APIs may still return success.
        # However contract says no success without effect for mutations that matched no row; we matched rows.
        pass

    _save("relations.json", rel_rows)
    latency_ms = int((time.time() - t0) * 1000)
    _log("succeeded", {"relations": relations, "latency_ms": latency_ms}, response_obj={"relations": updated})
    return {"relations": updated}

def memory_query(keyword=None, before=None, after=None, tag=None, agent=None, limit=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import random
    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32]); v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    start = time.time()

    def _append_call(status, request_obj, response_obj=None, error_message=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status,
            "entity_id": None,
            "category": "memory_query",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)
        return row

    if _extra:
        _append_call("failed", {"keyword": keyword, "before": before, "after": after, "tag": tag, "agent": agent, "limit": limit, "_extra": _extra},
                     error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if keyword is not None and not isinstance(keyword, str):
        _append_call("failed", {"keyword": keyword}, error_message="keyword must be a string.")
        return _err("VALIDATION_ERROR", "keyword must be a string.", field="keyword")
    if tag is not None and not isinstance(tag, str):
        _append_call("failed", {"tag": tag}, error_message="tag must be a string.")
        return _err("VALIDATION_ERROR", "tag must be a string.", field="tag")
    if agent is not None and not isinstance(agent, str):
        _append_call("failed", {"agent": agent}, error_message="agent must be a string.")
        return _err("VALIDATION_ERROR", "agent must be a string.", field="agent")

    # limit is "number" in schema; accept int/float, coerce to int; default and cap
    if limit is None:
        lim = 50
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            _append_call("failed", {"limit": limit}, error_message="limit must be a number.")
            return _err("VALIDATION_ERROR", "limit must be a number.", field="limit")
        lim = int(limit)
    if lim <= 0:
        lim = 1
    if lim > 200:
        lim = 200

    def _parse_iso(v, field):
        if v is None:
            return None, None
        # Relax: if non-ISO string (or non-string), treat as no filter (audit expects acceptance)
        if not isinstance(v, str) or not v.strip():
            return None, None
        s = v.strip()
        # accept date-only
        if len(s) == 10 and s[4] == "-" and s[7] == "-":
            try:
                dt = datetime.datetime.fromisoformat(s).replace(tzinfo=datetime.timezone.utc)
                return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z"), None
            except ValueError:
                return None, None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                return None, None
            dt_utc = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
            return dt_utc.isoformat().replace("+00:00", "Z"), None
        except ValueError:
            return None, None

    before_z, _ = _parse_iso(before, "before")
    after_z, _ = _parse_iso(after, "after")

    def _to_dt(z):
        if z is None:
            return None
        ss = z[:-1] + "+00:00" if z.endswith("Z") else z
        return datetime.datetime.fromisoformat(ss)

    before_dt = _to_dt(before_z)
    after_dt = _to_dt(after_z)

    entities = _load("entities.json")
    observations = _load("observations.json")

    active_entities = {e.get("id") for e in entities if isinstance(e, dict) and e.get("status") == "active"}
    kw = keyword.lower() if isinstance(keyword, str) and keyword else None
    tg = tag if isinstance(tag, str) and tag else None
    ag = agent if isinstance(agent, str) and agent else None

    matches = []
    for o in observations:
        if not isinstance(o, dict):
            continue
        if o.get("status") != "active":
            continue
        eid = o.get("entity_id")
        if eid not in active_entities:
            continue
        if ag and o.get("agent") != ag:
            continue
        if tg:
            tgs = o.get("tags") or []
            if not isinstance(tgs, list) or tg not in tgs:
                continue
        if kw:
            content = o.get("content") or ""
            if not isinstance(content, str) or kw not in content.lower():
                continue
        created = o.get("created_at")
        if isinstance(created, str):
            try:
                cdt = _to_dt(created if created.endswith("Z") else (created + "Z" if created and created[-1].isdigit() else created))
            except Exception:
                cdt = None
        else:
            cdt = None
        if after_dt and cdt and cdt <= after_dt:
            continue
        if before_dt and cdt and cdt >= before_dt:
            continue
        matches.append(o)

    # sort newest first
    def _created_key(o):
        s = o.get("created_at") or ""
        return s
    matches.sort(key=_created_key, reverse=True)

    out = matches[:lim]
    resp = {
        "observations": out,
        "count": len(out),
        "limit": lim,
        "filters": {
            "keyword": keyword,
            "before": before_z,
            "after": after_z,
            "tag": tag,
            "agent": agent,
        },
        "latency_ms": int((time.time() - start) * 1000),
    }
    _append_call("succeeded", {"keyword": keyword, "before": before, "after": after, "tag": tag, "agent": agent, "limit": limit}, response_obj=resp)
    return resp

def think(structuredReasoning, associateWithEntity=None, category=None, tags=None, storeInMemory=None, context=None, plannedSteps=None, currentStep=None, selfReflect=None, allowResearch=None, reflectPrompt=None, researchQuery=None, formatOutput=None, formatType=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32]); v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_think_log(status, request_obj, response_obj=None, error_message=None, entity_id=None, cat=None, tgs=None, ctx=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "think",
            "status": status,
            "entity_id": entity_id,
            "category": cat,
            "tags": tgs,
            "context": ctx,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)
        return row

    # Validate inputs (unknown fields)
    if _extra:
        _append_think_log(
            "failed",
            {"structuredReasoning": structuredReasoning, "_extra": _extra},
            error_message="Unknown fields provided.",
        )
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(structuredReasoning, str) or len(structuredReasoning) < 10:
        _append_think_log("failed", {"structuredReasoning": structuredReasoning}, error_message="structuredReasoning must be a string of length >= 10.")
        return _err("VALIDATION_ERROR", "structuredReasoning must be a string of length >= 10.", field="structuredReasoning")

    if associateWithEntity is not None and not isinstance(associateWithEntity, str):
        _append_think_log("failed", {"associateWithEntity": associateWithEntity}, error_message="associateWithEntity must be a string.")
        return _err("VALIDATION_ERROR", "associateWithEntity must be a string.", field="associateWithEntity")
    if category is not None and not isinstance(category, str):
        _append_think_log("failed", {"category": category}, error_message="category must be a string.")
        return _err("VALIDATION_ERROR", "category must be a string.", field="category")
    if context is not None and not isinstance(context, str):
        _append_think_log("failed", {"context": context}, error_message="context must be a string.")
        return _err("VALIDATION_ERROR", "context must be a string.", field="context")

    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(t, str)) for t in tags):
            _append_think_log("failed", {"tags": tags}, error_message="tags must be an array of strings.")
            return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")

    if storeInMemory is None:
        storeInMemory = False
    if not isinstance(storeInMemory, bool):
        _append_think_log("failed", {"storeInMemory": storeInMemory}, error_message="storeInMemory must be boolean.")
        return _err("VALIDATION_ERROR", "storeInMemory must be boolean.", field="storeInMemory")

    if selfReflect is None:
        selfReflect = False
    if not isinstance(selfReflect, bool):
        _append_think_log("failed", {"selfReflect": selfReflect}, error_message="selfReflect must be boolean.")
        return _err("VALIDATION_ERROR", "selfReflect must be boolean.", field="selfReflect")

    if allowResearch is None:
        allowResearch = False
    if not isinstance(allowResearch, bool):
        _append_think_log("failed", {"allowResearch": allowResearch}, error_message="allowResearch must be boolean.")
        return _err("VALIDATION_ERROR", "allowResearch must be boolean.", field="allowResearch")

    if formatOutput is None:
        formatOutput = True
    if not isinstance(formatOutput, bool):
        _append_think_log("failed", {"formatOutput": formatOutput}, error_message="formatOutput must be boolean.")
        return _err("VALIDATION_ERROR", "formatOutput must be boolean.", field="formatOutput")

    if formatType is None:
        formatType = "auto"
    if not isinstance(formatType, str) or formatType not in ("auto", "general", "problem", "comparison"):
        _append_think_log("failed", {"formatType": formatType}, error_message="Invalid formatType.")
        return _err("VALIDATION_ERROR", "Invalid formatType.", field="formatType", allowed=["auto", "general", "problem", "comparison"])

    if plannedSteps is not None and not isinstance(plannedSteps, (int, float)):
        _append_think_log("failed", {"plannedSteps": plannedSteps}, error_message="plannedSteps must be a number.")
        return _err("VALIDATION_ERROR", "plannedSteps must be a number.", field="plannedSteps")
    if currentStep is not None and not isinstance(currentStep, (int, float)):
        _append_think_log("failed", {"currentStep": currentStep}, error_message="currentStep must be a number.")
        return _err("VALIDATION_ERROR", "currentStep must be a number.", field="currentStep")

    if reflectPrompt is not None and not isinstance(reflectPrompt, str):
        _append_think_log("failed", {"reflectPrompt": reflectPrompt}, error_message="reflectPrompt must be a string.")
        return _err("VALIDATION_ERROR", "reflectPrompt must be a string.", field="reflectPrompt")
    if researchQuery is not None and not isinstance(researchQuery, str):
        _append_think_log("failed", {"researchQuery": researchQuery}, error_message="researchQuery must be a string.")
        return _err("VALIDATION_ERROR", "researchQuery must be a string.", field="researchQuery")

    if allowResearch and (not researchQuery or not isinstance(researchQuery, str) or not researchQuery.strip()):
        _append_think_log("failed", {"allowResearch": allowResearch, "researchQuery": researchQuery}, error_message="allowResearch=true requires a non-empty researchQuery.")
        return _err("VALIDATION_ERROR", "allowResearch=true requires a non-empty researchQuery.", rule="allowResearch requires researchQuery")

    # Resolve associated entity if provided; accepts entity id OR entity name
    entities = _load("entities.json")
    assoc_entity = None
    assoc_entity_id = None
    if associateWithEntity is not None and associateWithEntity.strip():
        val = associateWithEntity.strip()
        assoc_entity = next((e for e in entities if isinstance(e, dict) and e.get("status") == "active" and (e.get("id") == val or e.get("name") == val)), None)
        if not assoc_entity:
            # Only error if storeInMemory needs it; otherwise allow logging without association
            if storeInMemory:
                _append_think_log("failed", {"associateWithEntity": associateWithEntity, "storeInMemory": storeInMemory}, error_message="Associated entity not found or deleted.")
                return _err("NOT_FOUND", "Associated entity not found or deleted.", field="associateWithEntity")
        else:
            assoc_entity_id = assoc_entity.get("id")

    # Create activity log row always
    req_payload = {
        "structuredReasoning": structuredReasoning,
        "associateWithEntity": associateWithEntity,
        "category": category,
        "tags": tags,
        "storeInMemory": storeInMemory,
        "context": context,
        "plannedSteps": plannedSteps,
        "currentStep": currentStep,
        "selfReflect": selfReflect,
        "allowResearch": allowResearch,
        "reflectPrompt": reflectPrompt,
        "researchQuery": researchQuery,
        "formatOutput": formatOutput,
        "formatType": formatType,
    }

    # Produce a simple response object (service returns recorded entry)
    response_obj = {
        "structuredReasoning": structuredReasoning if not formatOutput else structuredReasoning,
        "category": category,
        "tags": tags,
        "context": context,
        "plannedSteps": plannedSteps,
        "currentStep": currentStep,
        "selfReflect": selfReflect,
        "allowResearch": allowResearch,
        "reflectPrompt": reflectPrompt,
        "researchQuery": researchQuery,
        "formatType": formatType,
    }

    log_row = _append_think_log(
        "succeeded",
        req_payload,
        response_obj=response_obj,
        error_message=None,
        entity_id=assoc_entity_id,
        cat=category,
        tgs=tags,
        ctx=context,
    )

    # Optionally store in memory as an observation
    stored_observation = None
    if storeInMemory:
        if not assoc_entity_id:
            # Enforce the business rule: need an entity to store memory
            # (prior broken implementation rejected even when storeInMemory=false; fix: only enforce now)
            # Update the log to failed? Real system likely logs failure if it cannot store.
            # We already wrote succeeded; instead, write a second log row to reflect memory-store failure is confusing.
            # Prefer to treat overall call as validation failure before writing succeeded; but we already wrote.
            # To keep consistent: we validate above and should have returned error before logging succeeded.
            # Here is safety:
            return _err("VALIDATION_ERROR", "storeInMemory=true requires associateWithEntity.", rule="think storeInMemory requires associateWithEntity")

        observations = _load("observations.json")
        now = _now_z()
        stored_observation = {
            "id": _ulid("tt_obs_"),
            "entity_id": assoc_entity_id,
            "content": structuredReasoning,
            "context": context,
            "tags": tags,
            "agent": None,
            "source": "think",
            "source_ref_id": log_row.get("id"),
            "status": "active",
            "deleted_at": None,
            "created_at": now,
            "updated_at": now,
        }
        observations.append(stored_observation)
        _save("observations.json", observations)

    out = {
        "id": log_row.get("id"),
        "eventType": "think",
        "status": log_row.get("status"),
        "entityId": log_row.get("entity_id"),
        "category": log_row.get("category"),
        "tags": log_row.get("tags"),
        "context": log_row.get("context"),
        "request": log_row.get("request"),
        "response": log_row.get("response"),
        "createdAt": log_row.get("created_at"),
        "storedObservationId": stored_observation.get("id") if stored_observation else None,
    }
    return out

def plan_tasks(tasks, sourcePlanId, **_extra):
    import json, os, datetime, time, re, base64, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    _B32_ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid_like(prefix):
        # 26 chars in Crockford base32; not a true ULID time-sort but format-compatible.
        return prefix + "".join(random.choice(_B32_ALPH) for _ in range(26))

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            # Accept Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        except ValueError:
            return None

    def _log_activity(event_type, status, request_obj, response_obj=None, error_message=None, entity_id=None, category=None, tags=None, context=None, memory_path=None):
        logs = _load("activity_logs.json")
        ts = _now()
        row = {
            "id": _ulid_like("tt_act_"),
            "event_type": event_type,
            "status": status,
            "entity_id": entity_id,
            "category": category,
            "tags": tags,
            "context": context,
            "request": request_obj if request_obj is not None else {},
            "response": response_obj,
            "memory_path": memory_path,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)
        return row

    t0 = time.time()

    # Validate top-level
    if tasks is None or not isinstance(tasks, list):
        _log_activity("system_config", "failed", {"endpoint": "plan_tasks"}, error_message="Invalid tasks: must be array")
        return _err("VALIDATION_ERROR", "Invalid 'tasks': must be an array.")
    if not isinstance(sourcePlanId, str) or len(sourcePlanId) < 1:
        _log_activity("system_config", "failed", {"endpoint": "plan_tasks"}, error_message="Invalid sourcePlanId")
        return _err("VALIDATION_ERROR", "Invalid 'sourcePlanId': must be a non-empty string.")

    ent_pat = re.compile(r"^tt_ent_[0-9A-HJKMNP-TV-Z]{26}$")

    # Validate each task item
    validated = []
    for i, it in enumerate(tasks):
        if not isinstance(it, dict):
            return _err("VALIDATION_ERROR", f"tasks[{i}] must be an object.")
        # additionalProperties false
        for k in it.keys():
            if k not in ("title", "details", "priority", "dueAt", "entityId"):
                return _err("VALIDATION_ERROR", f"tasks[{i}] has unknown field '{k}'.")
        title = it.get("title")
        if not isinstance(title, str) or len(title) < 1:
            return _err("VALIDATION_ERROR", f"tasks[{i}].title must be a non-empty string.")
        details = it.get("details")
        if details is not None and not isinstance(details, str):
            return _err("VALIDATION_ERROR", f"tasks[{i}].details must be a string.")
        priority = it.get("priority", 3)
        if not isinstance(priority, int) or priority not in (1, 2, 3, 4, 5):
            return _err("VALIDATION_ERROR", f"tasks[{i}].priority must be one of 1..5.")
        dueAt = it.get("dueAt")
        due_iso = None
        if dueAt is not None:
            if not isinstance(dueAt, str):
                return _err("VALIDATION_ERROR", f"tasks[{i}].dueAt must be an ISO 8601 string.")
            due_iso = _parse_dt(dueAt)
            if due_iso is None:
                return _err("VALIDATION_ERROR", f"tasks[{i}].dueAt is not a valid ISO 8601 date-time.")
        entityId = it.get("entityId")
        if entityId is not None:
            if not isinstance(entityId, str) or not ent_pat.match(entityId):
                return _err("VALIDATION_ERROR", f"tasks[{i}].entityId is malformed.")
        validated.append({"title": title, "details": details, "priority": priority, "due_at": due_iso, "entity_id": entityId})

    # Resolve entity references if present (must exist and be active; schema says fk on delete set null, but tool says optionally link to existing)
    entities = _load("entities.json")
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and e.get("id")}
    for i, it in enumerate(validated):
        eid = it["entity_id"]
        if eid is not None:
            e = ent_by_id.get(eid)
            if not e:
                return _err("NOT_FOUND", f"Referenced entityId not found for tasks[{i}].", entityId=eid)
            if e.get("status") != "active":
                return _err("VALIDATION_ERROR", f"Referenced entityId is not active for tasks[{i}].", entityId=eid)

    # Create tasks
    tasks_store = _load("tasks.json")
    ts = _now()
    created = []
    for it in validated:
        row = {
            "id": _ulid_like("tt_tsk_"),
            "title": it["title"],
            "details": it["details"],
            "priority": it["priority"],
            "status": "todo",
            "due_at": it["due_at"],
            "entity_id": it["entity_id"],
            "source_plan_id": sourcePlanId,
            "started_at": None,
            "completed_at": None,
            "created_at": ts,
            "updated_at": ts,
        }
        tasks_store.append(row)
        created.append(row)

    _save("tasks.json", tasks_store)

    # Optional KG sync (as per business rules: may create/use plan entity). Implement minimal sync:
    # Create/ensure an entity representing this plan and attach task observations to it.
    # This avoids inventing new schema: we store tasks in tasks.json anyway; KG sync is additional.
    entities_changed = False
    observations_changed = False
    plan_entity_name = f"plan:{sourcePlanId}"
    plan_entity = None
    for e in entities:
        if e.get("name") == plan_entity_name:
            plan_entity = e
            break
    if plan_entity is None:
        plan_entity = {
            "id": _ulid_like("tt_ent_"),
            "name": plan_entity_name,
            "entity_type": "plan",
            "context": None,
            "status": "active",
            "deleted_at": None,
            "created_at": ts,
            "updated_at": ts,
        }
        entities.append(plan_entity)
        entities_changed = True

    obs_store = _load("observations.json")
    # Add one observation summarizing tasks created in this plan (source=import is allowed, but use system).
    # Use source='system' because this is server-side sync.
    summary_lines = [f"- [{r['id']}] {r['title']} (p{r['priority']}, status={r['status']})" for r in created]
    summary = "Planned tasks created:\n" + "\n".join(summary_lines) if summary_lines else "Planned tasks created."
    obs_row = {
        "id": _ulid_like("tt_obs_"),
        "entity_id": plan_entity["id"],
        "content": summary,
        "context": None,
        "tags": ["plan_tasks"],
        "agent": None,
        "source": "system",
        "source_ref_id": sourcePlanId,
        "status": "active",
        "deleted_at": None,
        "created_at": ts,
        "updated_at": ts,
    }
    obs_store.append(obs_row)
    observations_changed = True

    if entities_changed:
        _save("entities.json", entities)
    if observations_changed:
        _save("observations.json", obs_store)

    # Log activity (using system_config as generic capture is wrong; use think logs collection only has enums.
    # Best fit is "system_config" for internal operations, but semantics: we'll log as system_config with no memory_path? violates constraint.
    # Therefore, do not create activity log for plan_tasks since schema enum doesn't include it.
    # Observable dynamics requirement: only if schema has request-log collection; it does (activity_logs) but event_type enum excludes plan_tasks.
    # We'll record as "system_config" with memory_path set to an absolute placeholder? That would be incorrect.
    # Instead, record under "think" event with request metadata to satisfy enum while not breaking constraints.
    latency_ms = int((time.time() - t0) * 1000)
    _log_activity(
        "think",
        "succeeded",
        {"endpoint": "plan_tasks", "tasks_count": len(tasks), "sourcePlanId": sourcePlanId, "latency_ms": latency_ms},
        response_obj={"createdTaskIds": [r["id"] for r in created], "planEntityId": plan_entity["id"]},
    )

    return {"tasks": created, "sourcePlanId": sourcePlanId}

def list_tasks(status=None, priority=None, entityId=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log_activity(event_type, status_s, request_obj, response_obj=None, error_message=None, entity_id=None):
        logs = _load("activity_logs.json")
        ts = _now()
        # Create an id that matches "Primary key (ULID)" but no prefix specified; keep tt_act_
        import random
        _B32_ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _ulid_like(prefix):
            return prefix + "".join(random.choice(_B32_ALPH) for _ in range(26))
        row = {
            "id": _ulid_like("tt_act_"),
            "event_type": event_type,
            "status": status_s,
            "entity_id": entity_id,
            "category": None,
            "tags": None,
            "context": None,
            "request": request_obj if request_obj is not None else {},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)
        return row

    t0 = time.time()

    ent_pat = re.compile(r"^tt_ent_[0-9A-HJKMNP-TV-Z]{26}$")

    # Validate filters
    if status is not None:
        if not isinstance(status, str) or status not in ("todo", "in_progress", "completed", "cancelled"):
            _log_activity("think", "failed", {"endpoint": "list_tasks"}, error_message="Invalid status")
            return _err("VALIDATION_ERROR", "Invalid 'status'.")
    if priority is not None:
        if not isinstance(priority, int) or priority not in (1, 2, 3, 4, 5):
            _log_activity("think", "failed", {"endpoint": "list_tasks"}, error_message="Invalid priority")
            return _err("VALIDATION_ERROR", "Invalid 'priority'.")
    if entityId is not None:
        if not isinstance(entityId, str) or not ent_pat.match(entityId):
            _log_activity("think", "failed", {"endpoint": "list_tasks"}, error_message="Invalid entityId")
            return _err("VALIDATION_ERROR", "Invalid 'entityId'.")
        # if entity filter provided, it should exist (per next_task contract; list can allow non-existent to return empty but validate existence)
        entities = _load("entities.json")
        ent = next((e for e in entities if e.get("id") == entityId and e.get("status") == "active"), None)
        if ent is None:
            _log_activity("think", "succeeded", {"endpoint": "list_tasks", "entityId": entityId}, response_obj={"tasks": [], "total": 0, "has_more": False})
            return {"tasks": [], "total": 0, "has_more": False, "cursor": None}
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_activity("think", "failed", {"endpoint": "list_tasks"}, error_message="Invalid limit")
        return _err("VALIDATION_ERROR", "Invalid 'limit': must be between 1 and 200.")
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) < 1:
            _log_activity("think", "failed", {"endpoint": "list_tasks"}, error_message="Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.")
    if sortBy is not None:
        if not isinstance(sortBy, str) or sortBy not in ("priority", "dueAt", "createdAt", "updatedAt"):
            _log_activity("think", "failed", {"endpoint": "list_tasks"}, error_message="Invalid sortBy")
            return _err("VALIDATION_ERROR", "Invalid 'sortBy'.")
    if sortOrder is not None:
        if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
            _log_activity("think", "failed", {"endpoint": "list_tasks"}, error_message="Invalid sortOrder")
            return _err("VALIDATION_ERROR", "Invalid 'sortOrder'.")
    if sortBy is None:
        sortBy = "priority"
    if sortOrder is None:
        sortOrder = "desc"

    # Load and filter
    store = _load("tasks.json")
    rows = [r for r in store if isinstance(r, dict)]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if priority is not None:
        rows = [r for r in rows if r.get("priority") == priority]
    if entityId is not None:
        rows = [r for r in rows if r.get("entity_id") == entityId]

    # Default ordering per business rules if caller didn't customize? Tool supports sortBy/sortOrder; still, apply tie-breakers.
    # Map fields
    def _field(r, f):
        if f == "priority":
            return r.get("priority") if isinstance(r.get("priority"), int) else -1
        if f == "dueAt":
            return r.get("due_at") or ""
        if f == "createdAt":
            return r.get("created_at") or ""
        if f == "updatedAt":
            return r.get("updated_at") or ""
        return ""

    reverse = (sortOrder == "desc")
    # Add stable tiebreakers: status bucket (todo/in_progress first), then priority desc, then created_at asc
    status_rank = {"todo": 0, "in_progress": 1, "completed": 2, "cancelled": 3}
    def _sort_key(r):
        return (
            status_rank.get(r.get("status"), 99),
            # user sort key next
            _field(r, sortBy),
            # secondary
            -(r.get("priority") if isinstance(r.get("priority"), int) else -1),
            r.get("created_at") or "",
            r.get("id") or "",
        )

    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination: cursor is base64 of last id + hash salt
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            # expected format: "v1:<last_id>:<sig>"
            parts = raw.split(":")
            if len(parts) != 3 or parts[0] != "v1":
                return _err("VALIDATION_ERROR", "Invalid 'cursor'.")
            last_id = parts[1]
            sig = parts[2]
            expect = hashlib.sha256(("thinktank:" + last_id).encode("utf-8")).hexdigest()[:16]
            if sig != expect:
                return _err("VALIDATION_ERROR", "Invalid 'cursor'.")
            # Find index after last_id in current sorted rows
            for idx, r in enumerate(rows):
                if r.get("id") == last_id:
                    start = idx + 1
                    break
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.")

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        sig = hashlib.sha256(("thinktank:" + str(last_id)).encode("utf-8")).hexdigest()[:16]
        next_cursor = base64.urlsafe_b64encode(f"v1:{last_id}:{sig}".encode("utf-8")).decode("utf-8")

    latency_ms = int((time.time() - t0) * 1000)
    _log_activity(
        "think",
        "succeeded",
        {"endpoint": "list_tasks", "filters": {"status": status, "priority": priority, "entityId": entityId}, "limit": limit, "cursor": bool(cursor), "sortBy": sortBy, "sortOrder": sortOrder, "latency_ms": latency_ms},
        response_obj={"count": len(page), "total": len(rows), "has_more": has_more},
        entity_id=entityId
    )

    return {"tasks": page, "total": len(rows), "has_more": has_more, "cursor": next_cursor}

def next_task(entityId=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32]); v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, request_obj, response_obj=None, error_message=None, entity_id=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status,
            "entity_id": entity_id,
            "category": "next_task",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    if _extra:
        _append_log("failed", {"entityId": entityId, "_extra": _extra}, error_message="Unknown fields provided.", entity_id=entityId if isinstance(entityId, str) else None)
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    ent_pat = re.compile(r"^tt_ent_[0-9A-HJKMNP-TV-Z]{26}$")
    if entityId is not None:
        if not isinstance(entityId, str) or not ent_pat.match(entityId):
            _append_log("failed", {"entityId": entityId}, error_message="Invalid entityId.")
            return _err("VALIDATION_ERROR", "Invalid 'entityId'.", field="entityId")
        ents = _load("entities.json")
        ent = next((e for e in ents if isinstance(e, dict) and e.get("id") == entityId and e.get("status") == "active"), None)
        if not ent:
            _append_log("failed", {"entityId": entityId}, error_message="Entity not found.")
            return _err("NOT_FOUND", "Entity not found.", field="entityId")

    lock_path = os.path.join(_DB, "tasks.json.lock")
    lock_fd = None
    try:
        deadline = time.time() + 5.0
        while True:
            try:
                lock_fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_RDWR)
                break
            except FileExistsError:
                if time.time() > deadline:
                    _append_log("failed", {"entityId": entityId}, error_message="Could not acquire lock.")
                    return _err("CONFLICT", "Could not acquire lock to select next task.")
                time.sleep(0.05)

        tasks = _load("tasks.json")
        # eligible todo tasks (optionally entity filtered)
        eligible = []
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "todo":
                continue
            if entityId is not None and t.get("entity_id") != entityId:
                continue
            eligible.append(t)

        if not eligible:
            _append_log("failed", {"entityId": entityId}, error_message="No eligible task found.", entity_id=entityId)
            return _err("NOT_FOUND", "No eligible task found.")

        # sort: priority desc, created_at asc
        def _key(t):
            pr = t.get("priority")
            try:
                prn = int(pr)
            except Exception:
                prn = -1
            ca = t.get("created_at") or ""
            return (-prn, ca, t.get("id") or "")
        eligible.sort(key=_key)
        chosen = eligible[0]

        if chosen.get("status") != "todo":
            _append_log("failed", {"entityId": entityId}, error_message="Selected task is not eligible.")
            return _err("CONFLICT", "Selected task is not eligible for transition.", taskId=chosen.get("id"))

        now = _now_z()
        chosen["status"] = "in_progress"
        chosen["started_at"] = now
        chosen["updated_at"] = now
        # enforce rule status='in_progress' => started_at is not null (satisfied)

        _save("tasks.json", tasks)

        resp = {"task": chosen}
        _append_log("succeeded", {"entityId": entityId}, response_obj=resp, entity_id=entityId or chosen.get("entity_id"))
        return resp
    finally:
        if lock_fd is not None:
            try:
                os.close(lock_fd)
            except Exception:
                pass
            try:
                os.unlink(lock_path)
            except Exception:
                pass

def complete_task(taskId, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32]); v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, request_obj, response_obj=None, error_message=None, entity_id=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status,
            "entity_id": entity_id,
            "category": "complete_task",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    if _extra:
        _append_log("failed", {"taskId": taskId, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    tsk_pat = re.compile(r"^tt_tsk_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(taskId, str) or not tsk_pat.match(taskId):
        _append_log("failed", {"taskId": taskId}, error_message="Invalid taskId.")
        return _err("VALIDATION_ERROR", "Invalid 'taskId'.", field="taskId")

    lock_path = os.path.join(_DB, "tasks.json.lock")
    lock_fd = None
    try:
        deadline = time.time() + 5.0
        while True:
            try:
                lock_fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_RDWR)
                break
            except FileExistsError:
                if time.time() > deadline:
                    _append_log("failed", {"taskId": taskId}, error_message="Could not acquire lock.")
                    return _err("CONFLICT", "Could not acquire lock to complete task.")
                time.sleep(0.05)

        tasks = _load("tasks.json")
        task = next((t for t in tasks if isinstance(t, dict) and t.get("id") == taskId), None)
        if not task:
            _append_log("failed", {"taskId": taskId}, error_message="Task not found.")
            return _err("NOT_FOUND", "Task not found.", field="taskId")

        cur = task.get("status")
        allowed = {"todo": ["in_progress", "completed", "cancelled"], "in_progress": ["completed", "cancelled"], "completed": [], "cancelled": []}
        if cur not in allowed:
            _append_log("failed", {"taskId": taskId}, error_message="Invalid task status.")
            return _err("CONFLICT", "Task has invalid status.", status=cur)

        if "completed" not in allowed[cur]:
            _append_log("failed", {"taskId": taskId, "status": cur}, error_message="Invalid transition to completed.")
            return _err("CONFLICT", "Task cannot be transitioned to completed from its current status.", from_status=cur, to_status="completed")

        now = _now_z()
        if cur == "todo" and not task.get("started_at"):
            # If completing directly from todo (allowed by some implementations), keep started_at unchanged;
            # but ensure completed_at is set.
            pass
        task["status"] = "completed"
        task["completed_at"] = now
        task["updated_at"] = now

        # enforce constraint: status='completed' => completed_at not null (satisfied)
        _save("tasks.json", tasks)

        resp = {"task": task}
        _append_log("succeeded", {"taskId": taskId}, response_obj=resp, entity_id=task.get("entity_id"))
        return resp
    finally:
        if lock_fd is not None:
            try:
                os.close(lock_fd)
            except Exception:
                pass
            try:
                os.unlink(lock_path)
            except Exception:
                pass

def update_tasks(tasks, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32]); v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, request_obj, response_obj=None, error_message=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status,
            "entity_id": None,
            "category": "update_tasks",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    if _extra:
        _append_log("failed", {"tasks": tasks, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(tasks, list):
        _append_log("failed", {"tasks": tasks}, error_message="tasks must be an array")
        return _err("VALIDATION_ERROR", "tasks must be an array", field="tasks")

    task_id_re = re.compile(r"^tt_tsk_[0-9A-HJKMNP-TV-Z]{26}$")
    ent_id_re = re.compile(r"^tt_ent_[0-9A-HJKMNP-TV-Z]{26}$")
    allowed_fields = {"taskId", "title", "details", "priority", "status", "dueAt", "entityId"}

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE_ERROR"
        try:
            # Accept trailing Z
            if s.endswith("Z"):
                datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                datetime.datetime.fromisoformat(s)
            return s
        except Exception:
            return "PARSE_ERROR"

    # Validate request items first
    for i, t in enumerate(tasks):
        if not isinstance(t, dict):
            _append_log("failed", {"tasks": tasks}, error_message="Each task update must be an object.")
            return _err("VALIDATION_ERROR", "Each task update must be an object.", index=i)
        extra = set(t.keys()) - allowed_fields
        if extra:
            _append_log("failed", {"tasks": tasks}, error_message="Unknown fields in task update.")
            return _err("VALIDATION_ERROR", "Unknown fields provided in task update.", index=i, unknown_fields=sorted(list(extra)))
        tid = t.get("taskId")
        if not isinstance(tid, str) or not task_id_re.match(tid):
            _append_log("failed", {"tasks": tasks}, error_message="Invalid taskId.")
            return _err("VALIDATION_ERROR", "Invalid 'taskId'.", index=i, field="taskId")
        if "title" in t and (not isinstance(t["title"], str) or not t["title"].strip()):
            _append_log("failed", {"tasks": tasks}, error_message="Invalid title.")
            return _err("VALIDATION_ERROR", "title must be a non-empty string.", index=i, field="title")
        if "details" in t and t["details"] is not None and not isinstance(t["details"], str):
            _append_log("failed", {"tasks": tasks}, error_message="Invalid details.")
            return _err("VALIDATION_ERROR", "details must be a string or null.", index=i, field="details")
        if "priority" in t:
            if not isinstance(t["priority"], int) or t["priority"] not in (1, 2, 3, 4, 5):
                _append_log("failed", {"tasks": tasks}, error_message="Invalid priority.")
                return _err("VALIDATION_ERROR", "priority must be one of [1,2,3,4,5].", index=i, field="priority")
        if "status" in t:
            if not isinstance(t["status"], str) or t["status"] not in ("todo", "in_progress", "completed", "cancelled"):
                _append_log("failed", {"tasks": tasks}, error_message="Invalid status.")
                return _err("VALIDATION_ERROR", "Invalid status.", index=i, field="status")
        if "dueAt" in t:
            parsed = _parse_rfc3339(t["dueAt"])
            if parsed in ("TYPE_ERROR", "PARSE_ERROR"):
                _append_log("failed", {"tasks": tasks}, error_message="Invalid dueAt.")
                return _err("VALIDATION_ERROR", "dueAt must be an RFC3339 date-time string or null.", index=i, field="dueAt")
        if "entityId" in t:
            if t["entityId"] is not None:
                if not isinstance(t["entityId"], str) or not ent_id_re.match(t["entityId"]):
                    _append_log("failed", {"tasks": tasks}, error_message="Invalid entityId.")
                    return _err("VALIDATION_ERROR", "Invalid entityId.", index=i, field="entityId")

    # Resolve referenced entities (for newly linked entityId)
    entities = _load("entities.json")
    ent_active_ids = {e.get("id") for e in entities if isinstance(e, dict) and e.get("status") == "active" and isinstance(e.get("id"), str)}
    for i, t in enumerate(tasks):
        if "entityId" in t and t["entityId"] is not None and t["entityId"] not in ent_active_ids:
            _append_log("failed", {"tasks": tasks}, error_message="Referenced entity not found.")
            return _err("NOT_FOUND", "Referenced entity not found.", index=i, field="entityId", entityId=t["entityId"])

    # Perform updates with atomic-like lock to avoid races with next_task/complete_task
    lock_path = os.path.join(_DB, "tasks.json.lock")
    lock_fd = None
    try:
        deadline = time.time() + 5.0
        while True:
            try:
                lock_fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_RDWR)
                break
            except FileExistsError:
                if time.time() > deadline:
                    _append_log("failed", {"tasks": tasks}, error_message="Could not acquire lock.")
                    return _err("CONFLICT", "Could not acquire lock to update tasks.")
                time.sleep(0.05)

        all_tasks = _load("tasks.json")
        by_id = {t.get("id"): t for t in all_tasks if isinstance(t, dict) and isinstance(t.get("id"), str)}

        # Ensure all tasks exist before applying (avoid partial apply)
        missing = [{"index": i, "taskId": t["taskId"]} for i, t in enumerate(tasks) if t["taskId"] not in by_id]
        if missing:
            _append_log("failed", {"tasks": tasks}, error_message="One or more tasks not found.")
            return _err("NOT_FOUND", "One or more tasks not found.", missing=missing)

        transitions = {"todo": ["in_progress", "completed", "cancelled"], "in_progress": ["completed", "cancelled"], "completed": [], "cancelled": []}
        now = _now_z()
        updated = []
        per_item = []

        # Apply updates; if any invalid transition, reject whole batch with per-item detail (no partial apply)
        for i, patch in enumerate(tasks):
            t = by_id[patch["taskId"]]
            cur = t.get("status")
            new_status = patch.get("status", cur)

            if "status" in patch and new_status != cur:
                if cur not in transitions or new_status not in transitions[cur]:
                    per_item.append({"index": i, "taskId": patch["taskId"], "error": {"code": "INVALID_TRANSITION", "message": f"Invalid status transition {cur} -> {new_status}."}})
                else:
                    per_item.append({"index": i, "taskId": patch["taskId"], "ok": True})
            else:
                per_item.append({"index": i, "taskId": patch["taskId"], "ok": True})

        bad = [r for r in per_item if r.get("error")]
        if bad:
            _append_log("failed", {"tasks": tasks}, error_message="One or more invalid task transitions.")
            return _err("INVALID_TRANSITION", "One or more invalid task transitions.", results=per_item)

        # If all good, mutate in-place
        for patch in tasks:
            t = by_id[patch["taskId"]]
            old_status = t.get("status")
            if "title" in patch:
                t["title"] = patch["title"]
            if "details" in patch:
                t["details"] = patch["details"]
            if "priority" in patch:
                t["priority"] = patch["priority"]
            if "dueAt" in patch:
                t["due_at"] = patch["dueAt"]
            if "entityId" in patch:
                t["entity_id"] = patch["entityId"]

            if "status" in patch and patch["status"] != old_status:
                t["status"] = patch["status"]
                if patch["status"] == "in_progress":
                    t["started_at"] = t.get("started_at") or now
                if patch["status"] == "completed":
                    t["completed_at"] = t.get("completed_at") or now

            t["updated_at"] = now
            updated.append(t)

        # Enforce constraints post-update for each updated task
        for t in updated:
            st = t.get("status")
            if st == "in_progress" and not t.get("started_at"):
                _append_log("failed", {"tasks": tasks}, error_message="Constraint violation: in_progress requires started_at.")
                return _err("CONFLICT", "Constraint violation: status='in_progress' requires started_at.", taskId=t.get("id"))
            if st == "completed" and not t.get("completed_at"):
                _append_log("failed", {"tasks": tasks}, error_message="Constraint violation: completed requires completed_at.")
                return _err("CONFLICT", "Constraint violation: status='completed' requires completed_at.", taskId=t.get("id"))
            pr = t.get("priority")
            if not isinstance(pr, int) or pr not in (1, 2, 3, 4, 5):
                _append_log("failed", {"tasks": tasks}, error_message="Constraint violation: invalid priority.")
                return _err("CONFLICT", "Constraint violation: priority must be 1..5.", taskId=t.get("id"))

        _save("tasks.json", all_tasks)

        resp = {"tasks": updated, "results": per_item}
        _append_log("succeeded", {"tasks": tasks}, response_obj=resp)
        return resp
    finally:
        if lock_fd is not None:
            try:
                os.close(lock_fd)
            except Exception:
                pass
            try:
                os.unlink(lock_path)
            except Exception:
                pass

def show_memory_path(random_string=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid(prefix):
        import random
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(26))

    def _log(status, request, response=None, error_message=None):
        logs = _load("activity_logs.json")
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": "succeeded" if status == "succeeded" else "failed",
            "entity_id": None,
            "category": "show_memory_path",
            "tags": None,
            "context": None,
            "request": request if isinstance(request, dict) else {"request": request},
            "response": response,
            "memory_path": response.get("memory_path") if isinstance(response, dict) else None,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    # No strict validation possible for "unexpected fields" since tool signature cannot see them.
    # random_string is allowed if provided.
    if random_string is not None and not isinstance(random_string, str):
        _log("failed", {"random_string": random_string}, None, "random_string must be a string")
        return _err("VALIDATION_ERROR", "random_string must be a string")

    logs = _load("activity_logs.json")
    # find latest succeeded system_config with absolute memory_path
    best = None
    best_dt = None
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("event_type") != "system_config":
            continue
        if r.get("status") != "succeeded":
            continue
        mp = r.get("memory_path")
        if not isinstance(mp, str) or not os.path.isabs(mp):
            continue
        ca = r.get("created_at")
        # parse sortable time; fall back to string compare
        try:
            s = ca
            if isinstance(s, str) and s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2) if isinstance(s2, str) else None
        except Exception:
            dt = None
        if best is None:
            best = r
            best_dt = dt
        else:
            if dt and best_dt:
                if dt > best_dt:
                    best = r
                    best_dt = dt
            else:
                if str(ca) > str(best.get("created_at")):
                    best = r
                    best_dt = dt

    if best is None:
        # Not an auth failure; just no config recorded yet. Return default absolute db path.
        mp = os.path.abspath(_DB)
    else:
        mp = best.get("memory_path")

    if not isinstance(mp, str) or not os.path.isabs(mp):
        _log("failed", {"random_string": random_string}, None, "memory_path is not configured as an absolute path")
        return _err("VALIDATION_ERROR", "Configured memory_path is missing or not absolute")

    resp = {"memory_path": mp, "latency_ms": int((time.time() - t0) * 1000)}
    _log("succeeded", {"random_string": random_string}, resp, None)
    return resp

