    if num_results is None:
        num_results = 5
    if not isinstance(num_results, (int, float)) or isinstance(num_results, bool):
        _log("failed", {"query": query, "num_results": num_results}, None, "num_results must be a number")
        return _err("VALIDATION_ERROR", "num_results must be a number", field="num_results")
    if int(num_results) != num_results:
        _log("failed", {"query": query, "num_results": num_results}, None, "num_results must be an integer")
        return _err("VALIDATION_ERROR", "num_results must be an integer", field="num_results")
    num_results = int(num_results)
    if num_results < 1 or num_results > 100:
        _log("failed", {"query": query, "num_results": num_results}, None, "num_results out of range")
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 100", field="num_results")

    if type is None:
        type = "auto"
    if type not in ("auto", "keyword", "neural"):
        _log("failed", {"query": query, "type": type}, None, "invalid type")
        return _err("VALIDATION_ERROR", "type must be one of auto|keyword|neural", field="type")

    cats = {"general", "company", "research paper", "news", "pdf", "github", "tweet", "personal site", "linkedin profile", "financial report"}
    if category is None:
        category = "general"
    if category not in cats:
        _log("failed", {"query": query, "category": category}, None, "invalid category")
        return _err("VALIDATION_ERROR", "Invalid category", field="category", allowed=sorted(cats))

    if live_crawl is None:
        live_crawl = "always"
    if live_crawl not in ("always", "fallback"):
        _log("failed", {"query": query, "live_crawl": live_crawl}, None, "invalid live_crawl")
        return _err("VALIDATION_ERROR", "live_crawl must be one of always|fallback", field="live_crawl")

    def _parse_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or len(s.strip()) == 0:
            raise ValueError(f"{field} must be a string date in ISO format")
        ss = s.strip()
        # Accept YYYY-MM-DD or datetime; validate via fromisoformat
        try:
            if ss.endswith("Z"):
                _ = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                _ = datetime.datetime.fromisoformat(ss) if ("T" in ss) else datetime.date.fromisoformat(ss)
        except Exception:
            raise ValueError(f"{field} must be a valid ISO date/datetime")
        return ss

    try:
        spd = _parse_date(start_published_date, "start_published_date")
        epd = _parse_date(end_published_date, "end_published_date")
    except ValueError as ve:
        _log("failed", {"query": query}, None, str(ve))
        return _err("VALIDATION_ERROR", str(ve))

    def _valid_domains(arr, field):
        if arr is None:
            return None
        if not isinstance(arr, list):
            raise ValueError(f"{field} must be an array of strings")
        for d in arr:
            if not isinstance(d, str) or len(d.strip()) == 0:
                raise ValueError(f"{field} must contain non-empty strings")
        return [d.strip().lower() for d in arr]

    try:
        inc = _valid_domains(include_domains, "include_domains")
        exc = _valid_domains(exclude_domains, "exclude_domains")
    except ValueError as ve:
        _log("failed", {"query": query}, None, str(ve))
        return _err("VALIDATION_ERROR", str(ve))

    # Offline deterministic "search": return synthetic results derived from query hash.
    qnorm = " ".join(query.strip().split())
    seed = int(hashlib.sha256(qnorm.encode("utf-8")).hexdigest()[:8], 16)

    domains_pool = [
        "example.com", "wikipedia.org", "github.com", "arxiv.org", "news.ycombinator.com",
        "nature.com", "science.org", "medium.com", "reuters.com", "bloomberg.com"
    ]
    if inc:
        domains_pool = inc[:]  # only include these
    if exc:
        domains_pool = [d for d in domains_pool if d not in set(exc)]
        if not domains_pool:
            domains_pool = ["example.com"]

    def _pick(i):
        # simple LCG
        return (seed * 1103515245 + 12345 + i * 2654435761) & 0x7fffffff

    results = []
    for i in range(num_results):
        r = _pick(i)
        dom = domains_pool[r % len(domains_pool)]
        slug = re.sub(r"[^a-z0-9]+", "-", qnorm.lower()).strip("-")[:60] or "query"
        url = f"https://{dom}/{slug}?r={r%100000}"
        title = f"{qnorm} — result {i+1}"
        snippet = f"Offline Exa search stub for '{qnorm}' (type={type}, category={category})."
        published = None
        # If date filters provided, keep a plausible published date
        if spd or epd:
            base = datetime.date(2024, 1, 1) + datetime.timedelta(days=(r % 365))
            published = base.isoformat()
        results.append({
            "title": title,
            "url": url,
            "id": f"exa_res_{r:08x}_{i}",
            "score": round(0.9 - i * 0.01, 3),
            "published_date": published,
            "snippet": snippet,
        })

    resp = {"results": results, "num_results": len(results), "type": type, "category": category, "live_crawl": live_crawl}
    req = {
        "query": query,
        "num_results": num_results,
        "type": type,
        "start_published_date": spd,
        "end_published_date": epd,
        "include_domains": inc,
        "exclude_domains": exc,
        "category": category,
        "live_crawl": live_crawl,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    _log("succeeded", req, resp, None)
    return resp

def exa_answer(question, max_citations=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid(prefix):
        import random
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(26))

    def _log(status, request, response=None, error_message=None):
        logs = _load("activity_logs.json")
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "exa_answer",
            "status": "succeeded" if status == "succeeded" else "failed",
            "entity_id": None,
            "category": None,
            "tags": None,
            "context": None,
            "request": request,
            "response": response,
            "memory_path": os.path.abspath(_DB),
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    if not isinstance(question, str) or len(question.strip()) < 5:
        _log("failed", {"question": question}, None, "question must be at least 5 characters")
        return _err("VALIDATION_ERROR", "question must be at least 5 characters", field="question")

    if max_citations is None:
        max_citations = 5
    if not isinstance(max_citations, (int, float)) or isinstance(max_citations, bool) or int(max_citations) != max_citations:
        _log("failed", {"question": question, "max_citations": max_citations}, None, "max_citations must be an integer")
        return _err("VALIDATION_ERROR", "max_citations must be an integer", field="max_citations")
    max_citations = int(max_citations)
    if max_citations < 1 or max_citations > 10:
        _log("failed", {"question": question, "max_citations": max_citations}, None, "max_citations out of range")
        return _err("VALIDATION_ERROR", "max_citations must be between 1 and 10", field="max_citations")

    qnorm = " ".join(question.strip().split())
    h = hashlib.sha256(qnorm.encode("utf-8")).hexdigest()
    # Offline "answer" with deterministic citations
    citations = []
    for i in range(max_citations):
        cid = h[i*6:(i+1)*6]
        citations.append({
            "id": f"exa_cit_{cid}_{i}",
            "url": f"https://example.com/source/{cid}",
            "title": f"Source {i+1} for: {qnorm[:60]}",
        })

    answer = (
        f"This is an offline Exa /answer-style response generated deterministically for the question:\n"
        f"{qnorm}\n\n"
        f"It cannot fetch the web in this environment, so the content is a placeholder; use citations/links as stubs."
    )

    resp = {"answer": answer, "citations": citations, "max_citations": max_citations}
    req = {"question": question, "max_citations": max_citations, "latency_ms": int((time.time() - t0) * 1000)}
    _log("succeeded", req, resp, None)
    return resp

def list_entities(q=None, entityType=None, searchInEntityType=None, limit=None, cursor=None, includeObservations=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Defaults
    if searchInEntityType is None:
        searchInEntityType = False
    if includeObservations is None:
        includeObservations = False
    if limit is None:
        limit = 50

    # Validate
    if q is not None and (not isinstance(q, str) or len(q.strip()) < 1):
        return _err("VALIDATION_ERROR", "q must be a non-empty string when provided.")
    if entityType is not None and (not isinstance(entityType, str) or len(entityType.strip()) < 1):
        return _err("VALIDATION_ERROR", "entityType must be a non-empty string when provided.")
    if not isinstance(searchInEntityType, bool):
        return _err("VALIDATION_ERROR", "searchInEntityType must be a boolean.")
    if not isinstance(includeObservations, bool):
        return _err("VALIDATION_ERROR", "includeObservations must be a boolean.")
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    # Decode cursor
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Load
    entities = _load("entities.json")
    observations = _load("observations.json") if includeObservations else None

    q_norm = q.strip().lower() if isinstance(q, str) else None
    et_norm = entityType.strip() if isinstance(entityType, str) else None

    # Filter active only
    rows = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("status") != "active":
            continue
        if et_norm is not None and e.get("entity_type") != et_norm:
            continue
        if q_norm is not None:
            name = (e.get("name") or "")
            et = (e.get("entity_type") or "")
            hay = name.lower()
            if searchInEntityType:
                hay2 = et.lower()
                if q_norm not in hay and q_norm not in hay2:
                    continue
            else:
                if q_norm not in hay:
                    continue
        rows.append(e)

    # Sort by updated_at desc (fallback created_at desc)
    def _dt_key(s):
        if not isinstance(s, str) or not s:
            return ""
        return s

    rows.sort(key=lambda r: (_dt_key(r.get("updated_at")), _dt_key(r.get("created_at")), r.get("id", "")), reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Attach observations if requested
    out = []
    obs_by_entity = None
    if includeObservations:
        obs_by_entity = {}
        for o in (observations or []):
            if not isinstance(o, dict):
                continue
            if o.get("status") != "active":
                continue
            eid = o.get("entity_id")
            if not isinstance(eid, str):
                continue
            obs_by_entity.setdefault(eid, []).append(o)
        # sort observations by created_at asc to be stable
        for eid in list(obs_by_entity.keys()):
            obs_by_entity[eid].sort(key=lambda r: (_dt_key(r.get("created_at")), r.get("id", "")))

    for e in page:
        item = dict(e)
        if includeObservations:
            item["observations"] = list(obs_by_entity.get(e.get("id"), []))
        out.append(item)

    # Log call
    logs = _load("activity_logs.json")
    def _ulid():
        import os
        # 48-bit ms timestamp + 80 bits randomness, Crockford base32
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        ts = ms & ((1 << 48) - 1)
        r = int.from_bytes(os.urandom(10), "big")
        v = (ts << 80) | r
        chars = []
        for _ in range(26):
            chars.append(crock[v & 31])
            v >>= 5
        return "".join(reversed(chars))

    latency_ms = int((time.time() - t0) * 1000)
    logs.append({
        "id": _ulid(),
        "event_type": "system_config",
        "status": "recorded",
        "entity_id": None,
        "category": "list_entities",
        "tags": None,
        "context": None,
        "request": {
            "q": q,
            "entityType": entityType,
            "searchInEntityType": searchInEntityType,
            "limit": limit,
            "cursor": cursor,
            "includeObservations": includeObservations
        },
        "response": {"total": total, "returned": len(out), "has_more": has_more, "latency_ms": latency_ms},
        "memory_path": os.path.abspath(_DB),
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("activity_logs.json", logs)

    return {
        "data": out,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

