def update_task(id, title=None, details=None, priority=None, status=None, dueAt=None, entityId=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32]); v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status0, request_obj, response_obj=None, error_message=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status0,
            "entity_id": None,
            "category": "update_task",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    if _extra:
        _append_log("failed", {"id": id, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(id, str) or not id.strip():
        _append_log("failed", {"id": id}, error_message="id must be non-empty")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")

    if title is not None and (not isinstance(title, str) or not title.strip()):
        _append_log("failed", {"id": id, "title": title}, error_message="Invalid title")
        return _err("VALIDATION_ERROR", "title must be a non-empty string.", field="title")

    if details is not None and not isinstance(details, str):
        _append_log("failed", {"id": id, "details": details}, error_message="Invalid details")
        return _err("VALIDATION_ERROR", "details must be a string.", field="details")

    if priority is not None:
        if not isinstance(priority, int) or priority < 1 or priority > 5:
            _append_log("failed", {"id": id, "priority": priority}, error_message="Invalid priority")
            return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 5.", field="priority")

    if status is not None:
        if not isinstance(status, str) or status not in ("todo", "in_progress", "completed", "cancelled"):
            _append_log("failed", {"id": id, "status": status}, error_message="Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE_ERROR"
        try:
            if s.endswith("Z"):
                datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                datetime.datetime.fromisoformat(s)
            return s
        except Exception:
            return "PARSE_ERROR"

    if dueAt is not None:
        parsed = _parse_rfc3339(dueAt)
        if parsed in ("TYPE_ERROR", "PARSE_ERROR"):
            _append_log("failed", {"id": id, "dueAt": dueAt}, error_message="Invalid dueAt")
            return _err("VALIDATION_ERROR", "dueAt must be an RFC3339 date-time string.", field="dueAt")

    if entityId is not None and (not isinstance(entityId, str) or not entityId.strip()):
        _append_log("failed", {"id": id, "entityId": entityId}, error_message="Invalid entityId")
        return _err("VALIDATION_ERROR", "entityId must be a non-empty string.", field="entityId")

    # lock for consistency with next_task/complete_task
    lock_path = os.path.join(_DB, "tasks.json.lock")
    lock_fd = None
    try:
        deadline = time.time() + 5.0
        while True:
            try:
                lock_fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_RDWR)
                break
            except FileExistsError:
                if time.time() > deadline:
                    _append_log("failed", {"id": id}, error_message="Could not acquire lock.")
                    return _err("CONFLICT", "Could not acquire lock to update task.")
                time.sleep(0.05)

        tasks = _load("tasks.json")
        t = next((x for x in tasks if isinstance(x, dict) and x.get("id") == id), None)
        if not t:
            _append_log("failed", {"id": id}, error_message="Task not found")
            return _err("NOT_FOUND", "Task not found.", field="id")

        # If entityId provided, ensure entity exists and active
        if entityId is not None:
            ent_re = re.compile(r"^tt_ent_[0-9A-HJKMNP-TV-Z]{26}$")
            if not ent_re.match(entityId):
                _append_log("failed", {"id": id, "entityId": entityId}, error_message="Invalid entityId format")
                return _err("VALIDATION_ERROR", "Invalid entityId format.", field="entityId")
            entities = _load("entities.json")
            ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == entityId and e.get("status") == "active"), None)
            if not ent:
                _append_log("failed", {"id": id, "entityId": entityId}, error_message="Entity not found")
                return _err("NOT_FOUND", "Entity not found.", field="entityId")

        transitions = {"todo": ["in_progress", "completed", "cancelled"], "in_progress": ["completed", "cancelled"], "completed": [], "cancelled": []}
        cur = t.get("status")
        if status is not None and status != cur:
            if cur not in transitions or status not in transitions[cur]:
                _append_log("failed", {"id": id, "from": cur, "to": status}, error_message="Invalid transition")
                return _err("INVALID_TRANSITION", "Invalid task status transition.", from_status=cur, to_status=status)

        now = _now_z()
        if title is not None:
            t["title"] = title
        if details is not None:
            t["details"] = details
        if priority is not None:
            t["priority"] = priority
        if dueAt is not None:
            t["due_at"] = dueAt
        if entityId is not None:
            t["entity_id"] = entityId
        if status is not None and status != cur:
            t["status"] = status
            if status == "in_progress":
                t["started_at"] = t.get("started_at") or now
            if status == "completed":
                t["completed_at"] = t.get("completed_at") or now
        t["updated_at"] = now

        if t.get("status") == "in_progress" and not t.get("started_at"):
            _append_log("failed", {"id": id}, error_message="Constraint violation: started_at required")
            return _err("CONFLICT", "Constraint violation: status='in_progress' requires started_at.", id=id)
        if t.get("status") == "completed" and not t.get("completed_at"):
            _append_log("failed", {"id": id}, error_message="Constraint violation: completed_at required")
            return _err("CONFLICT", "Constraint violation: status='completed' requires completed_at.", id=id)

        _save("tasks.json", tasks)
        resp = {"task": t}
        _append_log("succeeded", {"id": id, "title": title, "details": details, "priority": priority, "status": status, "dueAt": dueAt, "entityId": entityId}, response_obj=resp)
        return resp
    finally:
        if lock_fd is not None:
            try:
                os.close(lock_fd)
            except Exception:
                pass
            try:
                os.unlink(lock_path)
            except Exception:
                pass

def update_activity_log(id, status=None, errorMessage=None, response=None, tags=None, category=None, memoryPath=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        out = []
        v = ms
        for _ in range(10):
            out.append(_CROCKFORD[v % 32]); v //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCKFORD[random.getrandbits(5)])
        return prefix + "".join(out)

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status0, request_obj, response_obj=None, error_message=None):
        logs = _load("activity_logs.json")
        ts = _now_z()
        row = {
            "id": _ulid("tt_log_"),
            "event_type": "system_config",
            "status": status0,
            "entity_id": None,
            "category": "update_activity_log",
            "tags": None,
            "context": None,
            "request": request_obj if isinstance(request_obj, dict) else {"request": request_obj},
            "response": response_obj,
            "memory_path": None,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("activity_logs.json", logs)

    if _extra:
        _append_log("failed", {"id": id, "_extra": _extra}, error_message="Unknown fields provided.")
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(id, str) or not id.strip():
        _append_log("failed", {"id": id}, error_message="id must be non-empty")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")

    if status is not None and (not isinstance(status, str) or status not in ("recorded", "succeeded", "failed")):
        _append_log("failed", {"id": id, "status": status}, error_message="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if errorMessage is not None and not isinstance(errorMessage, str):
        _append_log("failed", {"id": id, "errorMessage": errorMessage}, error_message="Invalid errorMessage")
        return _err("VALIDATION_ERROR", "errorMessage must be a string.", field="errorMessage")

    if response is not None and not isinstance(response, dict):
        _append_log("failed", {"id": id, "response": response}, error_message="Invalid response")
        return _err("VALIDATION_ERROR", "response must be an object.", field="response")

    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _append_log("failed", {"id": id, "tags": tags}, error_message="Invalid tags")
            return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")

    if category is not None and not isinstance(category, str):
        _append_log("failed", {"id": id, "category": category}, error_message="Invalid category")
        return _err("VALIDATION_ERROR", "category must be a string.", field="category")

    if memoryPath is not None:
        if not isinstance(memoryPath, str) or not os.path.isabs(memoryPath):
            _append_log("failed", {"id": id, "memoryPath": memoryPath}, error_message="Invalid memoryPath")
            return _err("VALIDATION_ERROR", "memoryPath must be an absolute path.", field="memoryPath")

    logs = _load("activity_logs.json")
    row = next((l for l in logs if isinstance(l, dict) and l.get("id") == id), None)
    if not row:
        _append_log("failed", {"id": id}, error_message="Activity log not found")
        return _err("NOT_FOUND", "Activity log not found.", field="id")

    transitions = {"recorded": ["succeeded", "failed"], "succeeded": [], "failed": []}
    cur = row.get("status")
    if status is not None and status != cur:
        if cur not in transitions or status not in transitions[cur]:
            _append_log("failed", {"id": id, "from": cur, "to": status}, error_message="Invalid transition")
            return _err("INVALID_TRANSITION", "Invalid activity log status transition.", from_status=cur, to_status=status)

    now = _now_z()
    # limited metadata edits
    if status is not None:
        row["status"] = status
    if errorMessage is not None:
        row["error_message"] = errorMessage
    if response is not None:
        row["response"] = response
    if tags is not None:
        row["tags"] = tags
    if category is not None:
        row["category"] = category
    if memoryPath is not None:
        row["memory_path"] = memoryPath

    # constraint: event_type='system_config' => memory_path not null
    if row.get("event_type") == "system_config" and not row.get("memory_path"):
        _append_log("failed", {"id": id}, error_message="Constraint violation: system_config requires memory_path.")
        return _err("CONFLICT", "Constraint violation: event_type='system_config' requires memory_path.", id=id)

    row["updated_at"] = now
    _save("activity_logs.json", logs)

    resp = {"activityLog": row}
    _append_log("succeeded", {"id": id, "status": status, "errorMessage": errorMessage, "response": response, "tags": tags, "category": category, "memoryPath": memoryPath}, response_obj=resp)
    return resp

def list_activity_logs(eventType=None, status=None, entityId=None, category=None, tag=None, since=None, until=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0560000" if __import__("os").path.isdir("./environment_mix/0560000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            raise ValueError("timestamp must be a non-empty string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(ss)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            try:
                return _parse_rfc3339(v)
            except Exception:
                return None
        return None

    def _dt_key(dt):
        return dt.timestamp() if isinstance(dt, datetime.datetime) else None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict):
                return None
            # expect {"created_at": "...", "id": "..."}
            ca = payload.get("created_at")
            cid = payload.get("id")
            if not isinstance(ca, str) or not isinstance(cid, str) or not ca or not cid:
                return None
            dt = _to_dt(ca)
            if dt is None:
                return None
            return {"created_at": dt, "id": cid}
        except Exception:
            return None

    def _encode_cursor(created_at_str, id_str):
        payload = {"created_at": created_at_str, "id": id_str}
        raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "list_activity_logs"

    # Validate inputs
    if eventType is not None and (not isinstance(eventType, str) or len(eventType) < 1):
        return _err("VALIDATION_ERROR", "eventType must be a non-empty string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("recorded", "succeeded", "failed"):
            return _err("VALIDATION_ERROR", "status must be one of: recorded, succeeded, failed")
    if entityId is not None and (not isinstance(entityId, str) or len(entityId) < 1):
        return _err("VALIDATION_ERROR", "entityId must be a non-empty string")
    if category is not None and (not isinstance(category, str) or len(category) < 1):
        return _err("VALIDATION_ERROR", "category must be a non-empty string")
    if tag is not None and (not isinstance(tag, str) or len(tag) < 1):
        return _err("VALIDATION_ERROR", "tag must be a non-empty string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    since_dt = None
    until_dt = None
    if since is not None:
        if not isinstance(since, str) or not since:
            return _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string")
        try:
            since_dt = _parse_rfc3339(since)
        except Exception:
            return _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string")
    if until is not None:
        if not isinstance(until, str) or not until:
            return _err("VALIDATION_ERROR", "until must be an RFC3339 date-time string")
        try:
            until_dt = _parse_rfc3339(until)
        except Exception:
            return _err("VALIDATION_ERROR", "until must be an RFC3339 date-time string")

    if since_dt is not None and until_dt is not None and since_dt > until_dt:
        return _err("VALIDATION_ERROR", "since must be <= until")

    cur_decoded = _decode_cursor(cursor)
    if cursor is not None and cur_decoded is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")

    # Load data
    logs = _load("activity_logs.json")

    # Filter and validate rows' shape minimally
    def _row_created_at_dt(r):
        return _to_dt(r.get("created_at"))

    # Apply filters
    filtered = []
    for r in logs:
        if not isinstance(r, dict):
            continue
        et = r.get("event_type")
        st = r.get("status")
        eid = r.get("entity_id")
        cat = r.get("category")
        tags = r.get("tags")
        created_dt = _row_created_at_dt(r)
        if created_dt is None:
            continue

        if eventType is not None and et != eventType:
            continue
        if status is not None and st != status:
            continue
        if entityId is not None and eid != entityId:
            continue
        if category is not None and cat != category:
            continue
        if tag is not None:
            if not isinstance(tags, list) or tag not in tags:
                continue
        if since_dt is not None and created_dt < since_dt:
            continue
        if until_dt is not None and created_dt > until_dt:
            continue

        filtered.append(r)

    # Order by created_at desc, then id desc for stability
    def _sort_key(r):
        dt = _row_created_at_dt(r)
        return (_dt_key(dt) if dt else 0.0, r.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)
    total = len(filtered)

    # Cursor pagination: created_at desc; include rows strictly "before" cursor
    if cur_decoded is not None:
        ca = cur_decoded["created_at"]
        cid = cur_decoded["id"]

        def _is_before(r):
            rdt = _row_created_at_dt(r)
            rid = r.get("id") or ""
            if rdt is None:
                return False
            if rdt < ca:
                return True
            if rdt > ca:
                return False
            # same timestamp: use id descending order; "before" means id < cursor id in desc order
            # With desc order, items with larger id appear earlier; so "after cursor page" starts at smaller ids.
            return rid < cid

        filtered = [r for r in filtered if _is_before(r)]

    page = filtered[:limit]
    has_more = len(filtered) > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_ca = last.get("created_at")
        last_id = last.get("id")
        if isinstance(last_ca, str) and isinstance(last_id, str) and last_ca and last_id:
            next_cursor = _encode_cursor(last_ca, last_id)

    # Record service dynamics: append a request row to activity_logs as system event
    try:
        now = _now_iso()
        # Simple ULID-like id (time-based + randomness) using standard library only
        import random, string
        rid = now.replace("-", "").replace(":", "").replace("T", "").replace("Z", "")
        rid += "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(10))
        req_log = {
            "id": rid,
            "event_type": "system_config",
            "status": "succeeded",
            "entity_id": None,
            "category": "request_log",
            "tags": ["audit", endpoint],
            "context": None,
            "request": {
                "endpoint": endpoint,
                "filters": {
                    "eventType": eventType,
                    "status": status,
                    "entityId": entityId,
                    "category": category,
                    "tag": tag,
                    "since": since,
                    "until": until,
                    "limit": limit,
                    "cursor": cursor,
                },
            },
            "response": {
                "returned": len(page),
                "total_matched": total,
                "has_more": has_more,
            },
            "memory_path": os.path.abspath(_DB),
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(req_log)
        _save("activity_logs.json", logs)
    except Exception:
        # Must not raise; return results even if audit write fails.
        pass

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": {
            "logs": page,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "meta": {
            "order_by": [{"field": "created_at", "direction": "desc"}],
            "limit": limit,
            "cursor": cursor,
            "latency_ms": latency_ms,
        },
    }
